      "optionFeedback": {
        "Primer sklerozan kolanjit": "Primer sklerozan kolanjit kolestatik enzim yüksekliği yapabilir ve özellikle inflamatuvar bağırsak hastalığıyla ilişkisi nedeniyle ayırıcı tanıda önemlidir. Ancak PSC’de MRCP/ERCP’de intra ve ekstrahepatik safra yollarında multifokal darlık-genişleme paterni beklenir. Bu vakada safra yolları görüntülemesi dilatasyon veya boncuklanma göstermiyor, AMA belirgin pozitif ve tipik hasta profili orta yaşlı kadında kaşıntı-yorgunluk şeklinde. Bu nedenle PSC, bu veri zincirini PBC kadar iyi açıklamaz.",
        "Ekstrahepatik koledok taşı obstrüksiyonu": "Koledok taşı mekanik kolestaz, sağ üst kadran ağrısı, ateş veya sarılık ataklarıyla gelebilir; direkt bilirubin ve ALP/GGT yükselebilir. Ancak bu hastada aylar içinde gelişen kaşıntı ve halsizlik vardır, ateş ve kolik ağrı yoktur, ultrasonografide safra yolu dilatasyonu saptanmamıştır. AMA pozitifliği mekanik taş obstrüksiyonunu açıklamaz. Taş obstrüksiyonu olsaydı görüntüleme ve klinik daha akut/obstrüktif olurdu.",
        "Otoimmün hepatit": "Otoimmün hepatit genellikle hepatoselüler enzim yüksekliği, yüksek IgG, ANA/SMA pozitifliği ve interface hepatit paterniyle düşünülür. Bu vakada ALP ve GGT baskın yüksek, AST/ALT yalnız orta derecede artmış, IgM yüksek ve AMA pozitifliği ön plandadır. Otoimmün hepatit-PBC overlap nadiren olabilir; ancak verilen patern saf kolestatik otoimmün küçük safra yolu hastalığını destekler. Bu nedenle otoimmün hepatit en uygun tanı değildir.",
        "İlaç ilişkili akut hepatoselüler hasar": "İlaç ilişkili karaciğer hasarı kolestatik veya hepatoselüler patern yapabilir; yeni ilaç, bitkisel ürün veya antibiyotik öyküsü ayırıcı tanıda aranır. Bu hastada yeni ilaç kullanımı verilmemiş, tablo kronik kaşıntı-halsizlik ve pozitif otoantikorla ilerlemiştir. Ayrıca IgM yüksekliği ve AMA pozitifliği ilaç toksisitesinden çok primer biliyer kolanjiti destekler. İlaç hasarı tanısı ancak uygun maruziyet ve dışlama ile güçlenir.",
        "Primer biliyer kolanjit": "Bu seçenek doğrudur. Orta yaşlı kadında aylar süren kaşıntı ve halsizlik, ALP/GGT baskın kolestatik enzim yüksekliği, yüksek IgM, pozitif antimitochondrial antikor ve safra yolu dilatasyonu olmaması primer biliyer kolanjit için klasik bir örüntüdür. PBC küçük intrahepatik safra kanallarının otoimmün yıkımıyla gelişir; bu nedenle mekanik obstrüksiyon görüntüsü olmadan kolestaz bulguları oluşur. Tanıda kolestatik biyokimya ve PBC’ye özgü otoantikorlar çoğu hastada yeterince güçlüdür; tedavide ursodeoksikolik asit temel ilk basamaktır. Bu vaka PSC, taş obstrüksiyonu ve otoimmün hepatitten özellikle görüntüleme, otoantikor ve enzim paterniyle ayrılır."
      }
