    "question": "Bu hastada akromegali kuşkusunu biyokimyasal olarak değerlendirmek için en uygun ilk test aşağıdakilerden hangisidir?",
    "questionType": "Tanısal yaklaşım",
    "answerTarget": "Akromegali taramasında ilk biyokimyasal test",
    "diagnosis": {
      "correct": "Yaşa ve cinsiyete göre yorumlanan serum IGF-1 düzeyi ölçmek",
      "options": [
        "Random serum büyüme hormonu düzeyini tek ölçümle değerlendirmek",
        "Yaşa ve cinsiyete göre yorumlanan serum IGF-1 düzeyi ölçmek",
        "Hipofiz MR görüntülemesini biyokimyasal doğrulama olmadan ilk basamak yapmak",
        "Deksametazon supresyon testi ile kortizol yanıtını değerlendirmek",
        "TRH uyarı testi ile TSH ve prolaktin cevabını değerlendirmek"
      ],
      "question": "Bu hastada akromegali kuşkusunu biyokimyasal olarak değerlendirmek için en uygun ilk test aşağıdakilerden hangisidir?",
      "explanation": "Erişkinde akral büyüme, yüz hatlarında kabalaşma, terleme, karpal tünel yakınması, uyku apnesi, diyabet ve hipertansiyon birlikteliği akromegali kuşkusunu artırır. İlk biyokimyasal test yaş ve cinsiyete göre yorumlanan IGF-1 düzeyidir; rastgele GH güvenilir değildir ve hipofiz MR biyokimyasal kanıttan sonra yapılmalıdır.",
      "pearls": [
        "IGF-1 GH’ye göre daha stabil bir tarama belirtecidir.",
        "Random GH pulsatil salınım nedeniyle yanıltıcı olabilir.",
        "MR anatomiyi gösterir; hormon fazlalığını kanıtlamaz.",
        "OGTT’de GH baskılanmaması doğrulamada kullanılır."
      ],
      "optionFeedback": {
        "Random serum büyüme hormonu düzeyini tek ölçümle değerlendirmek": "Random büyüme hormonu tek ölçümü akromegali taraması için güvenilir değildir. GH pulsatil salınır; stres, uyku, egzersiz, glukoz ve beslenme durumundan etkilenir. Bu nedenle tek bir rastgele GH değeri normal veya yüksek çıkabilir ve klinik tabloyu yanlış yönlendirebilir. Akromegalide daha stabil biyokimyasal tarama IGF-1 ile yapılır; gerekirse oral glukoz yükleme testinde GH baskılanmamasıyla doğrulama güçlendirilir.",
        "Yaşa ve cinsiyete göre yorumlanan serum IGF-1 düzeyi ölçmek": "Bu seçenek doğrudur. Yüz hatlarında kabalaşma, yüzük ve ayakkabı numarasının artması, terleme, baş ağrısı, horlama, diyabet ve hipertansiyon birlikteliği akromegali için klinik kuşku oluşturur. İlk biyokimyasal tarama, yaş ve cinsiyete göre referans aralığıyla yorumlanan IGF-1 düzeyidir; IGF-1 GH’nin karaciğer aracılı etkisini daha stabil şekilde yansıtır. IGF-1 yüksekse tanı çoğu zaman oral glukoz yükleme testinde GH’nin baskılanmaması ve ardından hipofiz MR ile adenom lokalizasyonu değerlendirilerek tamamlanır. Böylece önce hormon fazlalığı kanıtlanır, sonra anatomik kaynak aranır.",
        "Hipofiz MR görüntülemesini biyokimyasal doğrulama olmadan ilk basamak yapmak": "Hipofiz MR akromegalide adenom lokalizasyonu için önemlidir; ancak biyokimyasal doğrulama yapılmadan ilk basamak olarak seçilmesi doğru değildir. Hipofizde insidental mikroadenomlar görülebilir ve yalnız görüntüleme klinik sendromu kanıtlamaz. Önce IGF-1 ile hormon fazlalığı gösterilmeli, ardından gerekirse OGTT ve MR ile tanısal süreç tamamlanmalıdır. Bu sıralama gereksiz görüntüleme yorum hatalarını azaltır.",
        "Deksametazon supresyon testi ile kortizol yanıtını değerlendirmek": "Deksametazon supresyon testi Cushing sendromu değerlendirmesinde kullanılır; akromegali taraması için uygun ilk test değildir. Bu hastada santral kilo artışı veya mor stria gibi Cushing bulgularından çok akral büyüme, yüz hatlarında kabalaşma, terleme ve uyku apnesi ön plandadır. Diyabet ve hipertansiyon iki hastalıkta da görülebilir; ancak ayakkabı/yüzük numarası artışı ve mandibular-prognatik değişim akromegaliye yönlendirir. Bu nedenle kortizol aksını test etmek ilk hedef değildir.",
        "TRH uyarı testi ile TSH ve prolaktin cevabını değerlendirmek": "TRH uyarı testi güncel akromegali tanısında ilk basamak değildir. Akromegali kuşkusunda problem TSH cevabından çok GH-IGF-1 eksenindeki kronik fazlalıktır. Prolaktin eşlik eden hipofiz adenomlarında ölçülebilir; fakat tanısal taramanın merkezi değildir. Bu hasta için en uygun başlangıç serum IGF-1 ölçümüdür."
      }
    },
