  "question": "Bu hastada acil yönetimde öncelikli basamak aşağıdakilerden hangisidir?",
  "questionType": "Acil tedavi",
  "answerTarget": "Yaşamı tehdit eden digoksin toksisitesinde antidot seçimi",
  "diagnosis": {
    "correct": "Digoksin-spesifik antikor fragmanı uygulamak",
    "options": [
      "Digoksini kesip yalnız serum düzeyini 24 saat sonra tekrar ölçmek",
      "Geçici transvenöz pacemaker takıp digoksini aynı dozda sürdürmek",
      "Potasyumu düşürmek için kalsiyum glukonat verip hasta stabil olana kadar beklemek",
      "Digoksin-spesifik antikor fragmanı uygulamak",
      "Amiodaron yüklemesi yapıp ventriküler ektopiyi baskılamak"
    ],
    "question": "Bu hastada acil yönetimde öncelikli basamak aşağıdakilerden hangisidir?",
    "explanation": "Kronik digoksin kullanımı, böbrek fonksiyon bozulması, gastrointestinal ve görsel semptomlar, bradikardi/AV blok, ventriküler ektopi, yüksek digoksin düzeyi ve hiperkalemi birlikte ağır digoksin toksisitesini gösterir. Hayatı tehdit eden aritmi veya belirgin hiperkalemi varlığında digoksin-spesifik antikor fragmanı antidot olarak verilmelidir.",
    "pearls": [
      "Digoksin toksisitesi yaşlı ve renal fonksiyon bozukluğu olan hastada daha kolay gelişir.",
      "Bulantı, iştahsızlık ve sarı-yeşil görme klasik klinik ipuçlarıdır.",
      "Bradikardi/AV blok ile ventriküler ektopinin birlikte olması digoksin için ayırt ettiricidir.",
      "Hiperkalemi ağır toksisiteyi ve antidot ihtiyacını güçlendirir."
    ],
    "optionFeedback": {
      "Digoksini kesip yalnız serum düzeyini 24 saat sonra tekrar ölçmek": "Digoksini kesmek gerekli bir adımdır; ancak bu vaka için tek başına yeterli değildir. Hastada bulantı, görsel yakınma, böbrek fonksiyon bozulması, bradikardi/AV blok, ventriküler ektopi ve hiperkalemi birlikte vardır. Bu bulgular yaşamı tehdit edebilecek digoksin toksisitesini düşündürür. Yalnız serum düzeyi tekrarını beklemek, membran pompası inhibisyonu ve aritmi riskini tedavisiz bırakır. Serum digoksin düzeyi klinikle birlikte yorumlanır; ağır toksisite klinik olarak yönetilir.",
      "Geçici transvenöz pacemaker takıp digoksini aynı dozda sürdürmek": "Geçici pacemaker bazı bradiaritmilerde gerekebilir; ancak digoksin toksisitesinde mekanik hız desteği temel toksini ortadan kaldırmaz ve invaziv girişim aritmi riskini artırabilir. Ayrıca digoksini aynı dozda sürdürmek açıkça hatalıdır. Vaka böbrek fonksiyon bozulması ve ilaç birikimiyle uyumludur; bradikardiye eşlik eden hiperkalemi ve ventriküler ektopi antidot ihtiyacını güçlendirir. Öncelik digoksin-spesifik antikor fragmanıdır.",
      "Potasyumu düşürmek için kalsiyum glukonat verip hasta stabil olana kadar beklemek": "Hiperkalemi tedavisinde kalsiyum glukonat birçok durumda membran stabilizasyonu sağlar; fakat digoksin toksisitesinde asıl problem Na/K-ATPaz inhibisyonu ve kardiyak glikozid etkisidir. Ağır digoksin zehirlenmesinde hiperkalemi antidot endikasyonlarından biridir; yalnız potasyumu semptomatik olarak düşürmeye çalışmak mekanizmayı düzeltmez. Ayrıca kalsiyum uygulaması tarihsel olarak tartışmalı bir alandır ve bu sorunun hedefi kalsiyumdan çok digoksin-spesifik Fab gereksinimini ayırt etmektir.",
      "Digoksin-spesifik antikor fragmanı uygulamak": "Bu seçenek doğrudur. Yaşlı, böbrek fonksiyonu bozulmuş ve diüretik kullanan bir hastada bulantı, sarı-yeşil görme, belirgin bradikardi/AV blok, ventriküler ektopi, yüksek digoksin düzeyi ve potasyum yüksekliği ağır digoksin toksisitesini gösterir. Digoksin-spesifik antikor fragmanları serbest digoksini bağlayarak doku etkisini azaltır ve hayatı tehdit eden aritmi/hiperkalemi varlığında en kritik tedavidir. Destek tedavisi, elektrolit düzeltme ve digoksinin kesilmesi de yapılır; ancak bu klinikte antidot geciktirilmemelidir.",
      "Amiodaron yüklemesi yapıp ventriküler ektopiyi baskılamak": "Amiodaron ventriküler aritmilerde kullanılan bir antiaritmiktir; ancak digoksin düzeyini artırabilir ve toksisiteyi kötüleştirebilir. Bu vakada ventriküler ektopinin nedeni muhtemelen kardiyak glikozid toksisitesidir, dolayısıyla aritmiyi yalnız antiaritmikle baskılamak mekanizmayı çözmez. Ayrıca bradikardi ve AV blok varken ek ritim baskılayıcı ilaçlar tehlikeli olabilir. Öncelik digoksini bağlayan antidottur."
    }
  },
  "shuffleOptions": false,
  "coreKnowledge": "Digoksin Na/K-ATPaz inhibisyonu ile kardiyak iletimi ve hücre içi iyon dengesini etkiler; toksisitede bradiaritmi, ventriküler ektopi ve hiperkalemi gelişebilir.",
  "examPearl": "Digoksin + bulantı/görme bozukluğu + AV blok/PVC + hiperkalemi = Fab antidotu düşün.",
  "whyCorrect": "Doğru seçenek yalnız destek tedavisi değil, toksinin serbest fraksiyonunu bağlayarak yaşamı tehdit eden elektrofizyolojik etkiyi azaltan özgül tedavidir.",
  "optionComparison": "Yanlış seçenekler bekleme, yanlış antiaritmik veya yalnız hız desteği gibi mekanizmayı çözmeyen yaklaşımlardır.",
