  "question": "Bu laboratuvar ve klinik paternini en iyi açıklayan süreç aşağıdakilerden hangisidir?",
  "questionType": "Laboratuvar paterni / tanı",
  "answerTarget": "Ateş ve sitopenilerde hiperinflamatuvar sendrom ayrımı",
  "diagnosis": {
    "correct": "Hemofagositik lenfohistiyositoz",
    "options": [
      "Demir eksikliği anemisinde reaktif trombositoz",
      "Hemofagositik lenfohistiyositoz",
      "Kronik hastalık anemisi",
      "İmmün trombositopenik purpura",
      "Megaloblastik anemi"
    ],
    "question": "Bu laboratuvar ve klinik paternini en iyi açıklayan süreç aşağıdakilerden hangisidir?",
    "explanation": "Uzayan ateş, splenomegali, pansitopeni, çok yüksek ferritin, hipertrigliseridemi, hipofibrinojenemi, transaminaz yüksekliği ve kemik iliğinde hemofagositoz HLH için güçlü bir hiperinflamatuvar örüntüdür. Bu tablo basit anemi veya izole trombositopeniden çok sitokin aracılı makrofaj aktivasyonu ve organ etkilenimini gösterir.",
    "pearls": [
      "HLH’de ateş ve splenomegali sık başlangıç bulgularıdır.",
      "İki veya daha fazla hücre serisinde düşüş tanısal zinciri güçlendirir.",
      "Ferritinin aşırı yükselmesi TUS sorularında en kuvvetli ipuçlarından biridir.",
      "Trigliserid yüksekliği ve fibrinojen düşüklüğü makrofaj aktivasyonu/sitokin fırtınası lehinedir.",
      "Tetikleyici enfeksiyon, malignite veya otoimmün hastalık araştırılır."
    ],
    "optionFeedback": {
      "Demir eksikliği anemisinde reaktif trombositoz": "Demir eksikliği anemisi halsizlik ve mikrositoz yapabilir, hatta reaktif trombositozla görülebilir; fakat bu vakadaki ateş, splenomegali, pansitopeni, çok yüksek ferritin, hipertrigliseridemi ve hipofibrinojenemi paternini açıklamaz. Demir eksikliğinde ferritin genellikle düşüktür, burada ise aşırı inflamatuvar ferritin yüksekliği vardır. Ayrıca trombositopeni demir eksikliğinin tipik başlangıç bulgusu değildir. Bu nedenle yalnız anemiye odaklanmak sistemik hiperinflamatuvar sendromu kaçırır.",
      "Hemofagositik lenfohistiyositoz": "Bu seçenek doğrudur. Uzayan yüksek ateş, splenomegali, iki-üç seriyi etkileyen sitopeni, ferritinin binler-on binler düzeyinde artması, hipertrigliseridemi, hipofibrinojenemi ve kemik iliğinde hemofagositoz HLH için güçlü bir patern oluşturur. HLH’de sitotoksik T hücresi/NK hücresi kontrolündeki bozulma makrofaj aktivasyonu ve sitokin fırtınasına yol açar. TUS açısından kilit nokta, bu tablonun basit enfeksiyon veya anemi değil, gecikirse hızla organ yetmezliğine ilerleyebilen hiperinflamatuvar bir acil olmasıdır. Tedavide tetikleyici enfeksiyon/malignite araştırılırken immünsüpresif/HLH odaklı tedavi geciktirilmemelidir.",
      "Kronik hastalık anemisi": "Kronik hastalık anemisi inflamasyonla ilişkili normositer veya hafif mikrositer anemi ve ferritin yüksekliği yapabilir; fakat ferritin genellikle bu kadar dramatik değildir ve tek başına splenomegali, lökopeni-trombositopeni, hipofibrinojenemi ve hipertrigliseridemiyi açıklamaz. Bu vakada anemi yalnız bir parça bulgudur; esas örüntü çoklu sitopeni ve hiperinflamasyondur. Kronik hastalık anemisi tanısı, ateş ve organomegaliyle seyreden bu ağır tabloyu hafife almak olur.",
      "İmmün trombositopenik purpura": "İmmün trombositopenik purpura izole trombositopeni ve mukokütanöz kanama ile gelir; hemoglobin ve lökosit genellikle korunur. Bu hastada yalnız trombosit düşüklüğü yok; anemi ve lökopeni de vardır. Ayrıca çok yüksek ferritin, hipertrigliseridemi, hipofibrinojenemi, splenomegali ve kemik iliğinde hemofagositoz ITP ile açıklanmaz. Bu nedenle ITP iyi bir trombositopeni çeldiricisi olsa da vakadaki sistemik inflamatuvar tabloya uymaz.",
      "Megaloblastik anemi": "Megaloblastik anemi makrositoz, B12/folat eksikliği, hipersegmente nötrofiller ve nörolojik bulgularla gelebilir. Pansitopeni yapabilmesi nedeniyle çeldirici olabilir; ancak burada MCV belirgin makrositik değildir, B12/folat paterninden söz edilmiyor ve ateş-splenomegali-çok yüksek ferritin-hipofibrinojenemi gibi hiperinflamatuvar bulgular ön plandadır. Kemik iliğinde hemofagositoz da megaloblastik aneminin beklenen açıklaması değildir. Bu nedenle doğru süreç HLH’dir."
    }
  },
