  "coreKnowledge": "HLH, sitotoksik T/NK hücre kontrol bozukluğu ve makrofaj aktivasyonu sonucunda sitokin fırtınası, ateş, sitopeni, organomegali ve koagülasyon-metabolizma bozuklukları yapan hayatı tehdit eden bir sendromdur.",
  "examPearl": "Ateş + splenomegali + sitopeni + ferritin çok yüksek + trigliserid yüksek + fibrinojen düşük = HLH düşün.",
  "whyCorrect": "Doğru seçenek yalnız bir kan serisi bozukluğunu değil, çoklu sitopeni ve aşırı inflamasyon paternini mekanizma düzeyinde açıklar.",
  "optionComparison": "Yanlış seçenekler anemi veya trombositopeninin dar nedenleridir; vakadaki sistemik ateş, organomegali ve koagülasyon-metabolik inflamasyon paternini karşılamaz.",
