  "question": "Stabil olan bu hastada acil yönetimde en uygun kaynak kontrol yaklaşımı hangisidir?",
  "questionType": "treatment",
  "answerTarget": "source_control_strategy",
  "diagnosis": {
    "correct": "BT eşliğinde perkütan apse drenajı ve intravenöz antibiyotik",
    "options": [
      "Yalnız intravenöz antibiyotik ve klinik izlem",
      "Acil Hartmann prosedürü ile rezeksiyon",
      "BT eşliğinde perkütan apse drenajı ve intravenöz antibiyotik",
      "Acil kolonoskopi ile lümen içinden drenaj",
      "Oral antibiyotikle ayaktan takip"
    ],
    "question": "Stabil olan bu hastada acil yönetimde en uygun kaynak kontrol yaklaşımı hangisidir?",
    "explanation": "Büyük, lokalize ve perkütan erişime uygun divertiküler apse varlığında stabil hastada kaynak kontrolü için perkütan drenajın intravenöz antibiyotikle birlikte uygulanması en uygun ilk yaklaşımdır. Diffüz peritonit veya şok olmadığı için acil rezeksiyon ilk basamak değildir; apsenin boyutu nedeniyle antibiyotik tek başına da yetersiz kalabilir.",
    "pearls": [
      "Divertiküler apsede boyut ve stabilite tedavi kararını belirler.",
      "Büyük ve drenaja uygun koleksiyonda antibiyotik + perkütan drenaj kaynak kontrolünü sağlar.",
      "Diffüz peritonit, serbest perforasyon veya instabilite varsa cerrahi eşik düşer."
    ],
    "optionFeedback": {
      "Yalnız intravenöz antibiyotik ve klinik izlem": "Yalnız intravenöz antibiyotik küçük, sınırlı ve genellikle 4 cm’nin altındaki divertiküler apselerde stabil hastada düşünülebilir. Bu vakada koleksiyon 6.2 cm ölçülmüş, ateş ve inflamatuvar yanıt belirginleşmiş, ayrıca apse perkütan erişime uygun tarif edilmiştir. Böyle bir hastada antibiyotik tek başına kaynak kontrolünü geciktirebilir ve başarısızlık riski artar. Peritonit veya şok olmadığı için doğrudan büyük rezeksiyon gerekmese de, apsenin boyutu nedeniyle antibiyotiğe drenaj eklemek daha doğru cerrahi karar zinciridir.",
      "Acil Hartmann prosedürü ile rezeksiyon": "Acil Hartmann prosedürü diffüz peritonit, serbest perforasyon, fekal kontaminasyon, hemodinamik instabilite veya perkütan/konservatif tedaviye yanıtsızlık durumunda güçlü bir seçenektir. Bu hastada lokalize apse vardır; yaygın defans, serbest hava, laktat yüksekliği veya şok bulgusu verilmemiştir. Bu nedenle ilk basamakta kolon rezeksiyonu yapmak gereğinden agresif olur ve stabil hastadaki aşamalı yaklaşım mantığını bozar. Cerrahi rezeksiyon, başarısız drenaj/antibiyotik sonrası veya elektif dönemde nüks-risk değerlendirmesiyle gündeme gelebilir.",
      "BT eşliğinde perkütan apse drenajı ve intravenöz antibiyotik": "Bu seçenek doğrudur. Sol alt kadran ağrısı, ateş, lökositoz ve BT’de sigmoid çevresinde 6.2 cm, hava-sıvı seviyesi içeren lokalize koleksiyon komplike divertikülitte büyük apse paternini oluşturur. Hasta stabil olduğu, diffüz peritonit taşımadığı ve apse perkütan erişime uygun olduğu için en uygun kaynak kontrolü BT eşliğinde perkütan drenajın intravenöz antibiyotikle birleştirilmesidir. Bu yaklaşım sepsisi kontrol eder, acil kolorektal rezeksiyon morbiditesini azaltır ve klinik düzelme sonrası kolonik değerlendirme/elektif planlama yapılmasına izin verir.",
      "Acil kolonoskopi ile lümen içinden drenaj": "Acil kolonoskopi akut divertikülit sırasında perforasyon riskini artırabileceği için apse drenajı amacıyla kullanılmaz. Kolonoskopi, malignite veya eşlik eden kolon patolojisini dışlamak için akut inflamasyon yatıştıktan sonra planlanabilir. Bu vakada sorun lümen içi bir polip ya da kanama değil, ekstraluminal lokalize koleksiyondur; dolayısıyla kolonoskopi kaynak kontrolü sağlamaz. Öğrenci burada ‘kolon hastalığı = kolonoskopi’ refleksine kapılmamalı, akut fazdaki güvenli kaynak kontrol yöntemini seçmelidir.",
      "Oral antibiyotikle ayaktan takip": "Oral antibiyotikle ayaktan takip, hafif ve komplike olmayan divertikülitte ya da çok seçilmiş düşük riskli hastalarda düşünülebilir. Bu olguda ateş, CRP yüksekliği, lökositoz ve 6 cm’den büyük lokalize apse vardır; hasta evde izlenecek basit divertikülit düzeyinde değildir. Ayaktan tedavi kaynak kontrolünü geciktirir, apse büyümesi ve sepsis riskini artırabilir. Stabil olması taburculuk anlamına değil, acil cerrahi yerine kontrollü invaziv drenaj yapılabileceği anlamına gelir."
    }
  },
  "coreKnowledge": "Komplike divertikülitte stabilite, apse boyutu ve yaygın peritonit varlığı tedavi yolunu belirler; büyük lokalize apsede drenaj + antibiyotik, diffüz peritonitte cerrahi kaynak kontrol ön plandadır.",
  "examPearl": "Stabil hasta + büyük lokalize divertiküler apse + perkütan erişim = antibiyotikle birlikte perkütan drenaj düşün.",
  "whyCorrect": "Doğru yaklaşım, hastanın stabil olması nedeniyle acil rezeksiyondan kaçınırken 6 cm’den büyük lokalize apsede antibiyotik tek başına bırakılmayacak şekilde kaynak kontrolü sağlar.",
  "optionComparison": "Seçenekler kaynak kontrol yoğunluğu açısından ayrılır: ayaktan/oral tedavi yetersiz, antibiyotik tek başına küçük apsede uygun, acil rezeksiyon peritonit/instabilite için ayrılır, perkütan drenaj bu vakanın stabil büyük apse kararına uyar.",
  "evidenceChain": [
    "Sol alt kadranda lokal hassasiyet ve ateş → sol kolon kaynaklı lokalize inflamatuvar süreç.",
    "Lökosit 16.800/µL ve CRP 184 mg/L → sistemik inflamatuvar yanıt.",
    "BT’de 6.2 × 4.8 cm loküle koleksiyon → antibiyotik tek başına başarısızlık riski yüksek büyük apse.",
    "Yaygın serbest hava, diffüz rebound ve laktat yüksekliği yok → acil rezeksiyon yerine kontrollü drenaj için stabil bağlam.",
    "Koleksiyon perkütan erişime uygun → drenajla kaynak kontrol yapılabilir."
  ],
  "whyWrong": "Yanlış seçenekler ya küçük/komplike olmayan hastaya uygun daha hafif tedaviyi ya da diffüz peritonit/instabilite için ayrılan daha agresif cerrahiyi temsil eder; bu vaka büyük ama lokalize apse ve stabilite arasında orta basamak kaynak kontrol gerektirir.",
