  "question": "Bu hastada dalağı korumayı hedefleyen en uygun ilk girişimsel yönetim hangisidir?",
  "questionType": "treatment",
  "answerTarget": "trauma_source_control",
  "diagnosis": {
    "correct": "Yoğun izlem altında splenik arter anjiyoembolizasyonu",
    "options": [
      "Sadece taburculuk önerisiyle ayaktan izlem",
      "Yoğun izlem altında splenik arter anjiyoembolizasyonu",
      "Acil total splenektomi",
      "Tanısal peritoneal lavaj",
      "Profilaktik antibiyotikle görüntüleme yapılmadan servis yatışı"
    ],
    "question": "Bu hastada dalağı korumayı hedefleyen en uygun ilk girişimsel yönetim hangisidir?",
    "explanation": "Hemodinamik stabil veya resüsitasyona yanıtlı künt dalak yaralanmasında BT’de aktif kontrast ekstravazasyonu varsa yoğun izlem koşullarında splenik arter anjiyoembolizasyonu dalağı koruyan uygun kaynak kontrol yaklaşımıdır. İnstabilite veya peritonit gelişirse cerrahiye geçilir.",
    "pearls": [
      "Travmada kararın ilk ayrımı stabil/instabil hastadır.",
      "Stabil dalak yaralanmasında aktif blush anjiyoembolizasyon eşiğini düşürür.",
      "İnstabilite ve eşlik eden cerrahi karın bulguları laparotomi endikasyonudur."
    ],
    "optionFeedback": {
      "Sadece taburculuk önerisiyle ayaktan izlem": "Ayaktan izlem, dalak yaralanması şüphesi olmayan veya minimal yaralanmalı, güvenli takip koşulları sağlanan çok düşük riskli hastalar için bile dikkatle seçilir. Bu hastada kontrastlı BT’de dalak laserasyonu ve aktif kontrast ekstravazasyonu vardır; bu, nonoperatif takip başarısızlığı ve gecikmiş kanama açısından yüksek riskli bir bulgudur. Hemodinamik olarak stabil olması taburculuk için değil, ameliyat yerine anjiyografik kaynak kontrol için fırsat oluşturur. Bu nedenle yalnız öneriyle gönderme ciddi güvenlik hatasıdır.",
      "Yoğun izlem altında splenik arter anjiyoembolizasyonu": "Bu seçenek doğrudur. Künt karın travması sonrası hasta şu anda sıvıya yanıtlı ve hemodinamik olarak stabildir; BT’de dalakta derin laserasyon, hemoperitoneum ve aktif kontrast blush izlenmektedir. Stabil hastada aktif arteriyel kanama işareti varsa nonoperatif yönetim yoğun monitörizasyonla birlikte splenik arter anjiyoembolizasyonunu içerir. Amaç dalağı korurken kanama odağını kontrol etmek, gereksiz laparotomiden kaçınmak ve olası kötüleşmede cerrahiye hızlı geçebilecek bir ortamda hastayı izlemektir.",
      "Acil total splenektomi": "Acil total splenektomi hemodinamik instabil, resüsitasyona yanıtsız veya peritonit/başka cerrahi karın yaralanması düşündüren hastada hayat kurtarıcıdır. Bu olguda hasta ilk sıvı yanıtı sonrası stabil kalmış, bilinç açık ve perfüzyon düzelmiştir; karar verdirici bulgu aktif blush olsa da stabilite anjiyoembolizasyonu mümkün kılar. Doğrudan splenektomi dalağı koruma şansını ortadan kaldırır ve postsplenektomi enfeksiyon riski gibi uzun dönem sonuçlar doğurur. Ancak hasta bozulursa cerrahi eşik hızla düşer.",
      "Tanısal peritoneal lavaj": "Tanısal peritoneal lavaj günümüzde seçilmiş çok sınırlı durumlar dışında kontrastlı BT ile yer değiştirmiştir; özellikle stabil hastada organ yaralanmasının derecesi ve aktif ekstravazasyon BT ile zaten gösterilmiştir. Lavaj pozitif olsa bile kanamanın dalaktan mı başka kaynaktan mı geldiğini veya arteriyel blush varlığını yeterince yönlendirmez. Bu vakada tanısal belirsizlik değil, gösterilmiş aktif splenik kanama odağı için tedavi seçimi söz konusudur. Bu nedenle lavaj zaman kaybettirir.",
      "Profilaktik antibiyotikle görüntüleme yapılmadan servis yatışı": "Antibiyotik profilaksisi, splenektomi sonrası aşı/profilaksi başlıklarıyla karıştırılmamalıdır. Bu hasta görüntülemesi yapılmış, aktif kontrast ekstravazasyonu saptanmış ve travmatik kanama riski olan bir hastadır; antibiyotik kanamayı kontrol etmez. Servis yatışı da tek başına yeterli değildir; aktif arteriyel blush varlığı yoğun monitörizasyon ve girişimsel radyolojiyle kaynak kontrol gerektirir. Antibiyotik ancak eşlik eden kontaminasyon veya spesifik endikasyon varsa ayrı değerlendirilir."
    }
  },
  "coreKnowledge": "Künt dalak travmasında hemodinamik stabilite korunuyorsa organ koruyucu nonoperatif yaklaşım mümkündür; aktif kontrast ekstravazasyonu varlığında bu yaklaşım sıklıkla anjiyoembolizasyonla desteklenir.",
  "examPearl": "Dalak travması + stabil hasta + BT’de aktif blush = yoğun izlem altında splenik arter embolizasyonu düşün.",
  "whyCorrect": "Doğru seçenek, aktif arteriyel kanama işaretini kontrol ederken hastanın anlık stabilitesinden yararlanarak dalağı koruma şansı verir.",
  "optionComparison": "Bu seçenekler travma yönetim basamaklarını temsil eder; ayaktan izlem ve servis yatışı yetersiz, tanısal lavaj gereksiz, splenektomi instabil hasta için uygun, anjiyoembolizasyon ise stabil aktif blush paternine uyar.",
  "evidenceChain": [
    "Sol yan üzerine düşme ve sol üst kadran ağrısı → dalak yaralanması riski.",
    "E-FAST’te perisplenik sıvı → intraabdominal kanama olasılığı.",
    "İlk sıvı sonrası TA 106/70 ve laktat 1.9 mmol/L → resüsitasyona yanıtlı/stabil bağlam.",
    "BT’de arteriyel blush ve hemoperitoneum → aktif kanama odağı.",
    "Yaygın peritonit ve serbest hava yok → acil laparotomi yerine organ koruyucu girişimsel yaklaşım olanağı."
  ],
  "whyWrong": "Yanlış seçenekler ya gösterilmiş aktif kanamayı izlemle bırakır ya da stabil hastada gereksiz tanısal/eski yöntem veya doğrudan splenektomi seçer; vaka anjiyoembolizasyonla kaynak kontrol için uygundur.",
