  "question": "Bu hastada en uygun girişimsel tedavi stratejisi hangisidir?",
  "questionType": "treatment",
  "answerTarget": "pancreatic_source_control",
  "diagnosis": {
    "correct": "Antibiyotik eşliğinde perkütan veya endoskopik drenajla step-up yaklaşım",
    "options": [
      "İlk 24 saatte açık nekrozektomi",
      "Profilaktik karbapenemle girişimsiz taburculuk",
      "Acil ERCP ile pankreatik nekrozun temizlenmesi",
      "Antibiyotik eşliğinde perkütan veya endoskopik drenajla step-up yaklaşım",
      "Total pankreatektomi ve splenektomi"
    ],
    "question": "Bu hastada en uygun girişimsel tedavi stratejisi hangisidir?",
    "explanation": "Pankreatit atağından haftalar sonra gelişen ateş, inflamasyon belirteçleri ve BT’de gaz içeren organize nekrotik koleksiyon enfekte walled-off necrosis ile uyumludur. Stabil hastada antibiyotikle birlikte perkütan veya endoskopik drenajla başlayan step-up yaklaşım, erken açık nekrozektomiye göre daha uygun ilk girişimsel stratejidir.",
    "pearls": [
      "Nekrotizan pankreatitte enfeksiyon şüphesinde antibiyotik gerekir.",
      "Organize koleksiyonda ilk girişim genellikle drenajdır; yanıt yoksa minimal invaziv nekrozektomiye ilerlenir.",
      "Erken açık nekrozektomi morbiditesi yüksek olduğu için mümkün olduğunca geciktirilir."
    ],
    "optionFeedback": {
      "İlk 24 saatte açık nekrozektomi": "Açık nekrozektomi enfekte pankreatik nekrozda artık ilk refleks değildir; özellikle erken dönemde yapıldığında kanama, fistül, organ yetmezliği ve mortalite riski yüksektir. Nekrotik koleksiyonun duvarlanması beklenebildiğinde girişim mümkün olduğunca geciktirilir ve önce daha az invaziv drenaj yöntemleri kullanılır. Bu hasta semptom başlangıcından yaklaşık beş hafta sonra, koleksiyonu organize olmuş halde gelmiştir; bu durum doğrudan erken açık cerrahi değil step-up drenaj için uygundur. Açık nekrozektomi, drenaj ve minimal invaziv yöntemler başarısız olursa sonraki basamak olabilir.",
      "Profilaktik karbapenemle girişimsiz taburculuk": "Profilaktik antibiyotik kavramı steril nekrozda gereksiz antibiyotik kullanımını anlatır; bu vakada ise ateş, lökositoz, CRP/prokalsitonin yüksekliği ve BT’de koleksiyon içinde gaz gibi enfeksiyon lehine bulgular vardır. Taburculuk veya yalnız antibiyotikle girişimsiz izlem, organize enfekte nekrozda kaynak kontrolünü geciktirir. Antibiyotik gerekli olabilir ama koleksiyon büyük ve semptomatiktir; kaynak kontrol stratejisiyle birlikte düşünülmelidir. Dolayısıyla bu seçenek hem hastanın ciddiyetini hem de enfekte nekroz yönetimini hafife alır.",
      "Acil ERCP ile pankreatik nekrozun temizlenmesi": "ERCP biliyer obstrüksiyon veya kolanjit eşlik eden safra taşı pankreatitinde erken dönemde değerlidir; pankreatik nekroz kavitesini temizleme yöntemi değildir. Bu hastada ana karar enfekte, organize nekrotik koleksiyonun drenajıdır. Koledokta taş, kolanjit veya progresif tıkanma bulgusu verilmemiştir. Endoskopik drenaj EUS eşliğinde transluminal yoldan yapılabilir; ancak bu ERCP ile papilla üzerinden nekrozu temizlemek anlamına gelmez. Bu ayrım TUS açısından önemlidir.",
      "Antibiyotik eşliğinde perkütan veya endoskopik drenajla step-up yaklaşım": "Bu seçenek doğrudur. Akut pankreatit sonrası dördüncü haftayı geçmiş, duvarlanan ve içinde gaz bulunan nekrotik koleksiyon enfekte walled-off necrosis paternindedir. Stabil ama septik yanıtı olan hastada antibiyotik başlanır; kaynak kontrol için anatomik uygunluğa göre perkütan veya endoskopik drenaj yapılır ve yanıt yetersizse minimal invaziv nekrozektomiye ilerleyen step-up yaklaşım uygulanır. Amaç erken açık cerrahinin morbiditesinden kaçınırken enfeksiyonu kontrol etmektir. Klinik kötüleşme, organ yetmezliği veya drenaja yanıtsızlık daha agresif girişim gerektirebilir.",
      "Total pankreatektomi ve splenektomi": "Total pankreatektomi ve splenektomi çok nadir, seçilmiş ve genellikle kontrol edilemeyen yıkıcı pankreatik patolojilerde düşünülebilecek aşırı agresif bir cerrahidir. Enfekte nekrozun standart ilk yönetimi organ çıkarma değil, antibiyotik ve drenaj temelli step-up kaynak kontrolüdür. Bu olguda pankreasın tamamını tutan kontrolsüz kanama, malignite veya cerrahi olarak zorunlu yaygın nekroz bilgisi yoktur. Böyle bir seçenek hem gereksiz morbidite taşır hem de modern nekrotizan pankreatit yönetim sıralamasına uymaz."
    }
  },
  "coreKnowledge": "Enfekte pankreatik nekrozda tedavi antibiyotik ve kaynak kontrolüdür; organize koleksiyonda perkütan/endoskopik drenajla başlayan step-up yaklaşım, doğrudan açık cerrahiye göre daha güvenli ilk stratejidir.",
  "examPearl": "Pankreatit sonrası >4 hafta + duvarlanmış nekroz + gaz/ateş = enfekte walled-off necrosis; ilk refleks step-up drenajdır.",
  "whyCorrect": "Doğru strateji, enfekte organize nekrotik koleksiyonda kaynak kontrolü sağlarken erken açık nekrozektominin morbiditesinden kaçınır.",
  "optionComparison": "Seçenekler invazivlik ve hedef açısından ayrılır: antibiyotik tek başına kaynak kontrolsüz, ERCP yanlış hedefli, erken açık cerrahi veya total rezeksiyon aşırı agresif, step-up yaklaşım anatomik ve zamansal bağlama uygundur.",
  "evidenceChain": [
    "Pankreatit başlangıcından 5 hafta sonra tekrar ateş ve ağrı → geç pankreatit komplikasyonu.",
    "Lökosit 18.200/µL, CRP 228 mg/L ve prokalsitonin 2.8 ng/mL → enfeksiyon lehine sistemik yanıt.",
    "BT’de 9.4 × 6.1 cm duvarlı heterojen koleksiyon → organize nekrotik koleksiyon.",
    "Koleksiyon içinde gaz odakları → enfekte nekroz olasılığını güçlendirir.",
    "Diffüz peritonit veya kontrolsüz kanama yok → erken açık cerrahi yerine drenajla step-up yaklaşım."
  ],
  "whyWrong": "Yanlış seçenekler enfekte nekrozun kaynak kontrol ihtiyacını göz ardı eder, biliyer ERCP endikasyonuyla karıştırır veya modern step-up sıralamasını atlayarak gereksiz agresif cerrahi önerir.",
