  "stem": "Hasta iki gün önce semptomatik safra taşı nedeniyle laparoskopik kolesistektomi geçirdiğini ve ilk gece ağrısının beklenenden fazla olmadığını anlatır. Sabah saatlerinde sağ üst kadranda künt ağrı ve omuza vuran rahatsızlık artmış, hemşireler dren torbasındaki sıvının renginin koyu sarı-yeşile döndüğünü fark etmiştir. Bulantısı hafiftir, tekrarlayan kusması yoktur. Ateş yükselmesi veya üşüme-titreme tariflemez; ancak ayağa kalkınca ağrının arttığını söyler. Operasyon öncesinde sarılık atağı veya ERCP öyküsü yoktur. Dren son 8 saatte belirgin miktarda sıvı toplamıştır.",
