  "question": "Bu stabil postoperatif hastada en uygun tedavi yaklaşımı hangisidir?",
  "questionType": "treatment",
  "answerTarget": "postoperative_complication_management",
  "diagnosis": {
    "correct": "ERCP ile sfinkterotomi ve biliyer stent yerleştirme",
    "options": [
      "ERCP ile sfinkterotomi ve biliyer stent yerleştirme",
      "Yalnız dren çekilerek ayaktan kontrol",
      "Acil geniş sağ hepatektomi",
      "Oral ursodeoksikolik asit ve yağsız diyet",
      "Kolonoskopi ile drenaj yerinin değerlendirilmesi"
    ],
    "question": "Bu stabil postoperatif hastada en uygun tedavi yaklaşımı hangisidir?",
    "explanation": "Post-kolesistektomi erken dönemde artan safra karakterli drenaj, dren bilirubininin serumdan yüksek olması ve sınırlı subhepatik koleksiyon düşük dereceli safra kaçağı paternini destekler. Stabil ve peritonitsiz hastada ERCP ile sfinkterotomi ve biliyer stent, kaçak hattındaki basıncı azaltarak iyileşmeyi sağlar.",
    "pearls": [
      "Postoperatif safra renkli drenajda dren sıvısı bilirubini değerlidir.",
      "Stabil düşük dereceli kaçakta ERCP + stent temel yaklaşımdır.",
      "Peritonit, kontrolsüz koleksiyon veya majör kanal transeksiyonu varsa cerrahi/hepatobiliyer merkez yaklaşımı gerekir."
    ],
    "optionFeedback": {
      "ERCP ile sfinkterotomi ve biliyer stent yerleştirme": "Bu seçenek doğrudur. Laparoskopik kolesistektomi sonrası ikinci günde sağ üst kadran ağrısı, ateş olmadan artan bilious drenaj, hafif bilirubin yüksekliği ve koleksiyon bulgusu sistik kanal güdüğü veya küçük safra yolu kaçağı paternini düşündürür. Hasta yaygın peritonit veya ağır sepsis taşımıyorsa ERCP ile basınç düşürme, sfinkterotomi ve biliyer stent yerleştirme çoğu düşük dereceli kaçakta etkili kaynak kontrol sağlar. Mevcut dren koleksiyonu boşaltıyor olabilir; ancak kaçağın devam etmesini azaltmak için endoskopik biliyer dekompresyon gerekir.",
      "Yalnız dren çekilerek ayaktan kontrol": "Dreni çekmek, devam eden safra kaçağında koruyucu yolu ortadan kaldırır ve intraabdominal biloma, peritonit veya sepsis riskini artırabilir. Bu hastada dren içeriği berrak seröz değil, miktarı artan safra renkli sıvıdır; ayrıca BT’de küçük subhepatik koleksiyon vardır. Ayaktan kontrol, klinik olarak tamamen iyi, drenajı azalan ve görüntüleme sorunu olmayan hastada düşünülebilir. Burada drenajın niteliği ve miktarı aktif kaçak lehinedir; dren korunmalı, gerekirse koleksiyon drenajı ve ERCP ile basınç düşürme planlanmalıdır.",
      "Acil geniş sağ hepatektomi": "Geniş sağ hepatektomi, kolesistektomi sonrası tipik sistik kanal güdüğü kaçağı için doğru hedefe yönelik bir işlem değildir ve aşırı agresif bir yaklaşımdır. Büyük ana hepatik kanal transeksiyonu, kompleks hiler yaralanma veya vasküler-biliyer yıkıcı yaralanmalar özel hepatobiliyer merkezde rekonstrüksiyon gerektirebilir; bu vakada ise düşük dereceli kaçak düşündüren drenaj ve sınırlı koleksiyon vardır. Peritonit ya da kontrolsüz sepsis yokken böyle bir rezeksiyon hem bilimsel hem cerrahi güvenlik açısından yanlıştır. Tedavi basınç düşürme ve drenaj prensibine dayanır.",
      "Oral ursodeoksikolik asit ve yağsız diyet": "Ursodeoksikolik asit kolestatik bazı durumlarda veya safra bileşimiyle ilişkili uzun dönem sorunlarda kullanılabilir; akut postoperatif safra kaçağını kapatacak bir kaynak kontrol yöntemi değildir. Yağsız diyet semptomu azaltabilir gibi görünse de sistik kanal güdüğü kaçağında basınç gradyanını endoskopik stent kadar düzeltemez. Bu hastada klinik sorun safra üretiminin kimyasal bileşimi değil, safra yolundan batına devam eden kaçaktır. Bu nedenle medikal diyet yaklaşımı yetersizdir.",
      "Kolonoskopi ile drenaj yerinin değerlendirilmesi": "Kolonoskopi kalın barsak lümeni ve mukozasını değerlendirir; kolesistektomi sonrası safra kaçağının tanı veya tedavisinde yeri yoktur. Dren yerinin değerlendirilmesi fizik muayene, dren karakteri, ultrason/BT, HIDA veya ERCP/MRCP gibi biliyer sisteme yönelik yöntemlerle yapılır. Bu seçenek anatomik hedefi tamamen yanlıştır ve cerrahi komplikasyon yönetiminde kaynak organı karıştırır. Postoperatif dönemde her drenaj problemi endoskopi anlamına gelmez; doğru endoskopik araç burada ERCP’dir."
    }
  },
  "coreKnowledge": "Post-kolesistektomi safra kaçaklarında stabil hastada drenajın korunması ve ERCP ile biliyer basıncın düşürülmesi çoğu sistik kanal güdüğü kaçağında etkili tedavidir.",
  "examPearl": "Kolesistektomi sonrası safra renkli drenaj + stabil hasta = ERCP ile sfinkterotomi/stent; dreni çekme tuzağına düşme.",
  "whyCorrect": "Doğru seçenek, devam eden safra kaçağında basınç gradyanını azaltır ve stabil hastada açık cerrahiden önce etkili kaynak kontrol sağlar.",
  "optionComparison": "Seçenekler hedef organ ve invazivlik açısından ayrılır; dreni çekmek tehlikeli, medikal diyet yetersiz, kolonoskopi anatomik olarak yanlış, hepatektomi aşırı agresif, ERCP/stent ise düşük dereceli biliyer kaçak paternine uygundur.",
  "evidenceChain": [
    "Postoperatif 2. gün safra renkli drenaj → erken biliyer komplikasyon şüphesi.",
    "Dren bilirubini 18 mg/dL ve serum bilirubininden yüksek → dren sıvısının safra karakterini destekler.",
    "TA 118/74, laktat verilmemiş ama perfüzyon iyi, yaygın rebound yok → stabil/peritonitsiz bağlam.",
    "Subhepatik 4.0 × 2.2 cm koleksiyon → sınırlı biloma/kaçak etkisi.",
    "Ana safra kanalında belirgin dilatasyon yok → basınç düşürücü endoskopik tedavi düşük dereceli kaçak için uygundur."
  ],
  "whyWrong": "Yanlış seçenekler aktif kaçağı göz ardı eder, anatomik olarak ilgisiz girişim önerir veya düşük dereceli stabil kaçakta gereksiz yıkıcı cerrahiye yönelir.",
  "availableInvestigations": [],
  "preserveInvestigationOrder": true,
