    "question": "Bu hastada multidisipliner tedavi planında en uygun yaklaşım hangisidir?",
    "questionType": "oncologic_treatment_sequence",
    "answerTarget": "locally_advanced_rectal_cancer_neoadjuvant_strategy",
    "diagnosis": {
      "correct": "Neoadjuvan sistemik tedavi ve/veya kemoradyoterapi sonrası total mezorektal eksizyon planlama",
      "options": [
        "Transanal lokal eksizyon ve patoloji sonucuna göre izlem",
        "Önce düşük anterior rezeksiyon ve total mezorektal eksizyon, ek tedaviyi patolojiye bırakma",
        "Neoadjuvan sistemik tedavi ve/veya kemoradyoterapi sonrası total mezorektal eksizyon planlama",
        "Yalnız palyatif loop kolostomi açıp onkolojik tedaviyi erteleme",
        "Antibiyotik tedavisi sonrası üç ay içinde kontrol kolonoskopisi"
      ],
      "question": "Bu hastada multidisipliner tedavi planında en uygun yaklaşım hangisidir?",
      "explanation": "Orta-alt rektum yerleşimli adenokarsinomda MRI yüksek risk bulguları, özellikle MRF/CRM’nin tehdit altında olması, EMVI pozitifliği ve nodal şüphe doğrudan cerrahi yerine neoadjuvan multimodal tedavi sonrası total mezorektal eksizyon planını gerektirir.",
      "pearls": [
        "Rektum kanserinde pelvik MRI tedavi sıralamasını belirler.",
        "MRF/CRM tehdidi doğrudan ameliyatta pozitif sınır riskini artırır.",
        "TME cerrahinin temelidir; ancak lokal ileri orta-alt tümörde zamanlama neoadjuvan tedavi sonrası olmalıdır."
      ],
      "optionFeedback": {
        "Transanal lokal eksizyon ve patoloji sonucuna göre izlem": "Transanal lokal eksizyon; genellikle küçük, erken evre, iyi seçilmiş T1 lezyonlarda, lenf nodu riski düşük ve lokal eksizyon sınırları güvenli olduğunda düşünülebilir. Bu hastada tümör anal verge’den 6 cm uzaklıkta, MRI’da T3 derinliği, şüpheli mezorektal nodlar, EMVI pozitifliği ve mezorektal fasyaya 1 mm mesafe vardır. Bu bulgular lokal nüks ve pozitif çevresel cerrahi sınır riski yüksek lokal ileri hastalığı gösterir. Lokal eksizyon hem mezorektal nodal hastalığı tedavi etmez hem de yüksek riskli tümörün onkolojik cerrahi prensiplerini karşılamaz.",
        "Önce düşük anterior rezeksiyon ve total mezorektal eksizyon, ek tedaviyi patolojiye bırakma": "Total mezorektal eksizyon rektum kanseri cerrahisinin temelidir; ancak her rektum kanseri doğrudan ameliyata gitmez. Orta-alt rektum yerleşimli, T3/T4, nod pozitif, EMVI pozitif veya mezorektal fasyayı tehdit eden tümörlerde önce neoadjuvan tedavi ile tümör yükünü azaltmak, çevresel sınır pozitifliğini ve lokal nüks riskini düşürmek amaçlanır. Bu vakada CRM/MRF mesafesinin 1 mm olması doğrudan cerrahiyi riskli hale getirir. Bu nedenle TME doğru cerrahi bile olsa zamanlama yanlıştır; önce multidisipliner neoadjuvan plan gerekir.",
        "Neoadjuvan sistemik tedavi ve/veya kemoradyoterapi sonrası total mezorektal eksizyon planlama": "Bu seçenek doğrudur. Kanlı mukus, tenesmus ve anal verge’den 6 cm’de ülserovejetan kitle klinik olarak orta-alt rektum tümörü ile uyumludur; biyopsi adenokarsinomdur. Pelvik MRI’da cT3c derinliği, şüpheli mezorektal nodlar, EMVI pozitifliği ve mezorektal fasyanın 1 mm’ye kadar yaklaşması lokal ileri ve yüksek riskli hastalık paternidir. Bu durumda amaç doğrudan cerrahiyle pozitif çevresel sınır riskine girmek değil; neoadjuvan sistemik tedavi ve/veya uzun-kısa şema radyoterapi içeren multidisipliner yaklaşım sonrası total mezorektal eksizyon planlamaktır. Böylece lokal kontrol, rezektabilite ve sfenkter/CRM güvenliği daha doğru değerlendirilir.",
        "Yalnız palyatif loop kolostomi açıp onkolojik tedaviyi erteleme": "Palyatif loop kolostomi; obstrüksiyon, perforasyon, kontrol edilemeyen semptom veya yaygın metastatik hastalık nedeniyle küratif yolun mümkün olmadığı seçilmiş durumlarda gerekebilir. Bu hastada ciddi obstrüksiyon veya uzak metastaz verilmemiştir; karın BT’de uzak metastaz yoktur ve performansı tedavi alabilecek düzeydedir. Bu nedenle yalnız kolostomi açıp onkolojik tedaviyi ertelemek küratif potansiyeli olan lokal ileri rektum kanserinde gereksiz eksik tedavidir. Diversiyon ancak semptom kontrolü için ek basamak olarak gündeme gelebilir, ana tedavi planı değildir.",
        "Antibiyotik tedavisi sonrası üç ay içinde kontrol kolonoskopisi": "Antibiyotik ve kontrol kolonoskopisi; divertikülit, enfeksiyöz kolit veya inflamatuvar durumlarda seçilmiş senaryolarda düşünülebilir. Bu hastada endoskopik biyopsi adenokarsinom göstermiş, MRI evreleme lokal ileri hastalık paternini ortaya koymuştur. Tedavi edilebilir rektum kanserini antibiyotikle izlemek kanserin ilerlemesine ve cerrahi/radyoterapi zamanlamasının kaybına yol açar. Kolonoskopi tanıyı koymuştur; şimdi gereken işlem enfeksiyon tedavisi değil multidisipliner onkolojik planlamadır."
      }
    },
    "coreKnowledge": "Orta-alt rektum kanserinde lokal evreleme pelvik MRI ile yapılır; T3/T4, nod pozitifliği, EMVI pozitifliği veya mezorektal fasya tehdidi varsa neoadjuvan tedavi sonrası TME onkolojik kontrol için temel yaklaşımdır.",
    "examPearl": "Rektum kanseri sorusunda ‘MRF/CRM 1 mm’ doğrudan cerrahiden çok neoadjuvan multimodal tedavi sinyalidir.",
    "whyCorrect": "Doğru seçenek, yalnız tanıyı değil MRI ile belirlenen lokal yüksek risk paternini ve cerrahi sınır güvenliğini tedavi sıralamasına bağlar.",
    "optionComparison": "Seçenekler onkolojik tedavi stratejisidir; lokal eksizyon erken düşük riskli T1 hastalıkta, upfront TME düşük riskli/üst rektum seçilmiş olgularda, palyatif diversiyon metastatik veya obstrüktif tabloda, antibiyotik izlem ise malignite dışı durumlarda düşünülebilir.",
    "evidenceChain": [
      "Kanlı mukus, tenesmus ve dışkı çapında incelme → rektal lezyon semptomları.",
      "Biyopsi invaziv adenokarsinom → tanı kesinleşmiş malignite.",
      "Anal verge’den 6 cm yerleşim → orta-alt rektum tedavi algoritması.",
      "MRI’da cT3c, şüpheli nod ve EMVI pozitifliği → lokal ileri yüksek risk.",
      "MRF’ye 1 mm mesafe → doğrudan cerrahide çevresel sınır riski."
    ],
    "whyWrong": "Yanlış seçenekler erken lokal hastalık, düşük riskli upfront cerrahi, palyatif durum veya enfeksiyon/izlem stratejilerini temsil eder; bu vaka lokal ileri ve küratif niyetli multimodal tedavi gerektirir.",
