    "question": "Bu hastada en olası postoperatif komplikasyon hangisidir?",
    "questionType": "postoperative_complication",
    "answerTarget": "colorectal_anastomotic_leak",
    "diagnosis": {
      "correct": "Kolorektal anastomoz kaçağına bağlı intraabdominal sepsis",
      "options": [
        "Postoperatif atelektazi",
        "İdrar yolu enfeksiyonu",
        "Clostridioides difficile koliti",
        "Kolorektal anastomoz kaçağına bağlı intraabdominal sepsis",
        "Yüzeyel cerrahi alan enfeksiyonu"
      ],
      "question": "Bu hastada en olası postoperatif komplikasyon hangisidir?",
      "explanation": "Kolorektal cerrahi sonrası 5. günde taşikardi, ateş, ileus, karın ağrısı, dren içeriği değişimi ve BT’de perianastomotik koleksiyon/kontrast kaçışı anastomoz kaçağına bağlı intraabdominal sepsis ile en iyi açıklanır.",
      "pearls": [
        "Postoperatif taşikardi anastomoz kaçağının erken uyarı bulgusu olabilir.",
        "İleus ve karın ağrısı eşlik ediyorsa yüzeyel yara veya atelektaziye bağlanmamalıdır.",
        "Stabil lokalize kaçakta drenaj; diffüz peritonit/septik şokta cerrahi kaynak kontrolü gerekir."
      ],
      "optionFeedback": {
        "Postoperatif atelektazi": "Postoperatif atelektazi özellikle erken postoperatif dönemde düşük dereceli ateş ve oksijen ihtiyacında hafif artışla gündeme gelebilir. Ancak tek başına atelektazi genellikle belirgin abdominal hassasiyet, ileus, laktat yüksekliği, dren içeriğinde bulanık-kötü kokulu değişim ve BT’de perianastomotik gaz-sıvı koleksiyonu oluşturmaz. Bu hastadaki taşikardi ve sepsis paternini yalnız akciğer bazal havalanma azalmasıyla açıklamak güvenli değildir. Cerrahi hastada postoperatif 4–7. gün taşikardi + karın bulgusu varsa öncelik intraabdominal komplikasyonu dışlamaktır.",
        "İdrar yolu enfeksiyonu": "İdrar yolu enfeksiyonu postoperatif ateş nedenlerinden biridir; özellikle sonda kullanımı, dizüri, piyüri, bakteriüri veya suprapubik hassasiyet varsa düşünülür. Bu vakada idrarla ilişkili yakınma verilmemiş, ana bulgular karında artan ağrı, distansiyon, ileus, yüksek inflamasyon belirteçleri ve anastomoz çevresinde gaz-sıvı koleksiyonudur. Üriner enfeksiyon taşikardi yapabilir, fakat perianastomotik koleksiyon ve oral kontrast kaçışını açıklamaz. Bu nedenle üriner kaynak, vakadaki cerrahi anatomik bulgular yanında ikincil ve zayıf kalır.",
        "Clostridioides difficile koliti": "Clostridioides difficile koliti antibiyotik kullanımı sonrası sulu ishal, kramp tarzı karın ağrısı, lökositoz ve ateşle gelebilir. Bu hastada belirgin sulu ishal yerine gaz-gaita çıkışının azalması, distansiyon ve ileus vardır; BT bulgusu yaygın kolit değil anastomoz komşuluğunda lokal gaz-sıvı koleksiyon ve kontrast kaçışıdır. C. difficile önemli bir postoperatif ayırıcı tanıdır, ancak bu senaryoda temel veri kolon mukozal enfeksiyonunu değil cerrahi bağlantı hattından sızıntıyı destekler. Yanlış seçenek, antibiyotik sonrası ateşe aşırı odaklanma tuzağıdır.",
        "Kolorektal anastomoz kaçağına bağlı intraabdominal sepsis": "Bu seçenek doğrudur. Kolorektal cerrahi sonrası 5. günde açıklanamayan taşikardi, ateş, artan karın ağrısı, ileus, CRP/prokalsitonin yüksekliği ve laktat artışı anastomoz kaçağı açısından güçlü uyarı işaretleridir. Dren renginin bulanık-kötü kokulu hale gelmesi ve BT’de anastomoz çevresinde gaz-sıvı koleksiyonu ile rektal kontrastın koleksiyona geçmesi tanısal zinciri güçlendirir. Stabil ve lokalize koleksiyonda antibiyotik + perkütan drenaj düşünülebilir; diffüz peritonit, septik şok veya kontrolsüz kontaminasyonda relaparotomi ve diversiyon gerekebilir. TUS mantığında postoperatif taşikardi çoğu zaman en erken ve en değerli alarm bulgusudur.",
        "Yüzeyel cerrahi alan enfeksiyonu": "Yüzeyel cerrahi alan enfeksiyonu kesi yerinde kızarıklık, ısı artışı, hassasiyet ve pürülan akıntıyla seyreder; sistemik bulgu yapabilir ama intraabdominal koleksiyon ve rektal kontrast ekstravazasyonunu açıklamaz. Bu vakada kesi yerinde sınırlı enfeksiyon bulgusu değil, karın içi sepsis ve ileus bulguları ön plandadır. Yüzeyel enfeksiyon tanısına takılıp BT’deki perianastomotik veriyi görmezden gelmek kaynak kontrolünü geciktirir. Bu nedenle seçenek postoperatif ateş çeldiricisidir ama doğru komplikasyon değildir."
      }
    },
    "coreKnowledge": "Kolorektal anastomoz kaçağı sıklıkla postoperatif 4–7. gün taşikardi, ateş, ileus, karın ağrısı, dren değişikliği ve perianastomotik koleksiyonla belirginleşir; tedavi hastanın stabilitesi ve kontaminasyonun yaygınlığına göre antibiyotik, drenaj veya reoperasyon içerir.",
    "examPearl": "Kolorektal cerrahi sonrası açıklanamayan taşikardi + ileus + yüksek CRP/prokalsitonin = anastomoz kaçağını dışla.",
    "whyCorrect": "Doğru seçenek, postoperatif zamanlama ve BT-dren bulgularını aynı komplikasyon mekanizmasında birleştirir.",
    "optionComparison": "Seçeneklerin hepsi postoperatif ateş nedenleridir; ayırıcı nokta karın içi koleksiyon, kontrast kaçışı, ileus ve dren içeriği değişiminin anastomoz hattını işaret etmesidir.",
    "evidenceChain": [
      "Postoperatif 5. gün yeni taşikardi ve ateş → cerrahi komplikasyon için kritik zamanlama.",
      "Gaz-gaita çıkışının azalması ve distansiyon → postoperatif ileus/sepsis etkisi.",
      "Drenin bulanık-kahverengi ve kötü kokulu hale gelmesi → enterik kontaminasyon kuşkusu.",
      "CRP/prokalsitonin ve laktat yüksekliği → intraabdominal sepsis ciddiyeti.",
      "BT’de perianastomotik gaz-sıvı koleksiyonu ve kontrast geçişi → anastomoz hattı kaynaklı kaçak."
    ],
    "whyWrong": "Yanlış seçenekler postoperatif ateşin sık nedenleridir; ancak hiçbiri anastomoz çevresi koleksiyon ve kontrast kaçışını açıklamaz.",
