    "question": "Bu hasta için en uygun definitif tedavi yaklaşımı hangisidir?",
    "questionType": "definitive_treatment",
    "answerTarget": "symptomatic_primary_hyperparathyroidism_surgery",
    "diagnosis": {
      "correct": "Odaklanmış paratiroidektomi için endokrin cerrahi planlama",
      "options": [
        "Oral kalsiyum ve D vitamini yüklemesiyle izlem",
        "Sadece tiyazid diüretik başlanması",
        "Adrenalektomi ile eş zamanlı eksplorasyon",
        "Bisfosfonat tedavisiyle cerrahiyi süresiz erteleme",
        "Odaklanmış paratiroidektomi için endokrin cerrahi planlama"
      ],
      "question": "Bu hasta için en uygun definitif tedavi yaklaşımı hangisidir?",
      "explanation": "Tekrarlayan nefrolitiazis, hiperkalsemi, uygunsuz yüksek PTH, hiperkalsiüri ve düşük kemik mineral yoğunluğu semptomatik primer hiperparatiroidi paternidir. Definitif tedavi uygun cerrahi adayında paratiroidektomidir; lokalizasyon cerrahi planı destekler.",
      "pearls": [
        "Primer hiperparatiroidi tanısı biyokimyasaldır: yüksek kalsiyum + uygunsuz yüksek PTH.",
        "Nefrolitiazis veya osteoporoz varsa hasta semptomatik/hedef organ etkilenimli kabul edilir.",
        "Sestamibi/USG tanı koymaz; ameliyatı lokalize etmeye yardım eder."
      ],
      "optionFeedback": {
        "Oral kalsiyum ve D vitamini yüklemesiyle izlem": "Kalsiyum ve D vitamini yüklemesi, eksiklik veya sekonder hiperparatiroidi bağlamında dikkatle ele alınabilir; ancak bu hastada kalsiyum zaten yüksek, PTH uygunsuz şekilde yüksek ve tekrarlayan böbrek taşı vardır. Kontrolsüz kalsiyum yükü hiperkalsemiyi ve hiperkalsiüriyi artırarak taş riskini kötüleştirebilir. D vitamini eksikliği olsaydı dikkatli replasman ayrı değerlendirilirdi, fakat burada temel sorun otonom PTH fazlalığıdır. Semptomatik primer hiperparatiroidide definitif tedavi eksikliği gidermek değil patolojik paratiroid dokusunu çıkarmaktır.",
        "Sadece tiyazid diüretik başlanması": "Tiyazidler idrarla kalsiyum atılımını azaltabilir ve bazı taş hastalarında hiperkalsiüri yönetiminde kullanılabilir; fakat hiperkalsemik primer hiperparatiroidide tek başına kullanımı serum kalsiyumunu artırabilir. Bu vakada PTH yüksekliği, hiperkalsemi, hipofosfatemi, hiperkalsiüri, nefrolitiazis ve kemik mineral yoğunluğu kaybı vardır. Dolayısıyla problem basit hiperkalsiüri değil, cerrahi olarak düzeltilebilecek primer hiperparatiroididir. Bu yaklaşım, doğru tanıyı ve definitif cerrahi tedaviyi geciktiren hatalı bir yönetim yoludur.",
        "Adrenalektomi ile eş zamanlı eksplorasyon": "Adrenalektomi adrenal korteks veya medulla kaynaklı cerrahi hastalıklarda uygulanır; paratiroid adenomu veya primer hiperparatiroidi için anatomik ve fizyolojik olarak doğru hedef değildir. Hastanın ataklar halinde hipertansiyon, katekolamin yüksekliği veya adrenal kitle bulgusu yoktur. Görüntülemede paratiroid lokalizasyonu sol inferior bölgede odak göstermektedir. Bu seçenek endokrin cerrahi organlarını karıştırma tuzağıdır; doğru cerrahi hedef paratiroid bezidir.",
        "Bisfosfonat tedavisiyle cerrahiyi süresiz erteleme": "Bisfosfonatlar kemik mineral yoğunluğunu artırmada yardımcı olabilir, özellikle cerrahi yapılamayan veya geçici medikal yönetim gereken hastalarda düşünülebilir. Ancak semptomatik primer hiperparatiroidide, özellikle tekrarlayan nefrolitiazis ve belirgin hiperkalsemi varken cerrahiyi süresiz ertelemez ve biyokimyasal kür sağlamaz. Bu hastada taş öyküsü ve distal radius T skorunun düşük olması hedef organ etkisini göstermektedir. Medikal kemik koruma, uygun cerrahi adayında paratiroidektominin yerine geçmez.",
        "Odaklanmış paratiroidektomi için endokrin cerrahi planlama": "Bu seçenek doğrudur. Hiperkalsemi ile birlikte PTH’nin baskılanmamış/yüksek olması primer hiperparatiroidi biyokimyasını oluşturur; hipofosfatemi, hiperkalsiüri, tekrarlayan nefrolitiazis ve düşük kemik mineral yoğunluğu hedef organ etkisini gösterir. Semptomatik hastada paratiroidektomi definitif tedavidir. Sestamibi ve ultrasonun aynı bölgede odak göstermesi cerrah için lokalizasyon sağlar; lokalizasyon tanı koymak için değil, ameliyat planını yönlendirmek için kullanılır. Uygun hastada deneyimli endokrin cerrah tarafından odaklanmış paratiroidektomi veya gerekli durumda bilateral boyun eksplorasyonu planlanır."
      }
    },
    "coreKnowledge": "Primer hiperparatiroidide semptomatik hastalarda ve hedef organ etkilenimi olanlarda paratiroidektomi definitif tedavidir; lokalizasyon görüntülemeleri biyokimyasal tanıdan sonra cerrahi stratejiyi belirlemek için kullanılır.",
    "examPearl": "Kalsiyum yüksek + PTH yüksek + taş/osteoporoz = endokrin cerrahi sorusunda paratiroidektomi düşün.",
    "whyCorrect": "Doğru seçenek, laboratuvar tanısını hedef organ etkilenimiyle birleştirerek definitif cerrahi tedaviye ulaşır.",
    "optionComparison": "Seçenekler endokrin/metabolik yönetim stratejileridir; kalsiyum yükleme ve tiyazid hiperkalsemiyi kötüleştirebilir, bisfosfonat yardımcı olabilir ama kür sağlamaz, adrenalektomi yanlış organdır.",
