    "question": "Bu hasta için en uygun meme cerrahisi ve adjuvan tedavi yaklaşımı hangisidir?",
    "questionType": "breast_surgery_treatment",
    "answerTarget": "localized_dcis_breast_conserving_surgery_radiation",
    "diagnosis": {
      "correct": "İşaretleme eşliğinde meme koruyucu eksizyon, temiz cerrahi sınır hedefi ve ardından radyoterapi planı",
      "options": [
        "İşaretleme eşliğinde meme koruyucu eksizyon, temiz cerrahi sınır hedefi ve ardından radyoterapi planı",
        "Neoadjuvan kemoterapi sonrası rutin aksiller diseksiyon",
        "Antibiyotik tedavisi ve altı ay sonra kontrol mamografi",
        "Sadece insizyonel biyopsi yapıp eksizyonu erteleme",
        "Lumpektomi yapılacak her hastaya rutin aksiller lenf nodu diseksiyonu ekleme"
      ],
      "question": "Bu hasta için en uygun meme cerrahisi ve adjuvan tedavi yaklaşımı hangisidir?",
      "explanation": "Nonpalpabl, görüntüleme ile sınırlı, kor biyopside invazyon göstermeyen DCIS’te lezyon meme koruyucu cerrahiye uygunsa işaretleme eşliğinde eksizyon ve negatif sınır hedeflenir; ardından radyoterapi lokal nüks riskini azaltır. Aksiller diseksiyon ve kemoterapi saf DCIS için rutin değildir.",
      "pearls": [
        "DCIS noninvazivdir; temel tedavi lokal cerrahidir.",
        "Lumpektomi yapılan saf DCIS’te aksiller cerrahi rutin değildir.",
        "Mastektomi planlanırsa veya invazyon kuşkusu yüksekse sentinel nod ayrıca düşünülür."
      ],
      "optionFeedback": {
        "İşaretleme eşliğinde meme koruyucu eksizyon, temiz cerrahi sınır hedefi ve ardından radyoterapi planı": "Bu seçenek doğrudur. Palpe edilmeyen, mamografide pleomorfik kümelenmiş mikrokalsifikasyonlarla saptanan ve kor biyopside invazyon göstermeyen sınırlı DCIS’te temel tedavi cerrahi eksizyondur. Lezyon meme koruyucu cerrahiye uygunsa işaretleme eşliğinde eksizyon yapılır ve negatif cerrahi sınır hedeflenir; sonrasında radyoterapi lokal nüks riskini azaltmak için planlanır. ER pozitiflik varsa endokrin risk azaltıcı tedavi ayrıca tartışılabilir. Sentinel lenf nodu biyopsisi lumpektomi yapılacak saf DCIS’te rutin değildir; mastektomi planlanıyorsa veya invazyon şüphesi yüksekse gündeme gelir.",
        "Neoadjuvan kemoterapi sonrası rutin aksiller diseksiyon": "Neoadjuvan kemoterapi ve rutin aksiller diseksiyon invaziv, özellikle nod pozitif veya belirli biyolojik alt tiplerde lokal ileri meme kanseri senaryolarında düşünülür. Bu vakada fizik muayenede kitle/aksiller nod yok, kor biyopsi invazyon göstermemiş ve görüntüleme sınırlı mikrokalsifikasyon alanı tariflemiştir. DCIS noninvaziv bir lezyondur; sistemik kemoterapi standart başlangıç tedavisi değildir. Aksiller diseksiyon da morbiditesi yüksek olduğu için saf DCIS ve klinik nod negatif hastada gereksizdir.",
        "Antibiyotik tedavisi ve altı ay sonra kontrol mamografi": "Antibiyotik ve mamografi kontrolü mastit veya apse gibi enfeksiyöz meme yakınmalarında düşünülebilir; burada ateş, ağrılı eritem, fluktuasyon veya enfeksiyon kliniği yoktur. Tarama mamografisinde pleomorfik mikrokalsifikasyon saptanmış ve stereotaktik biyopsi yüksek dereceli DCIS göstermiştir. Bu bulgu izlemle geçmesi beklenen bir enfeksiyon değil, eksizyon gerektiren preinvaziv neoplastik süreçtir. Altı ay beklemek invaziv odak varsa gecikmeye ve lezyon yayılımının artmasına yol açabilir.",
        "Sadece insizyonel biyopsi yapıp eksizyonu erteleme": "İnsizyonel biyopsi, modern meme cerrahisinde tanı amacıyla çoğu durumda kor biyopsinin yerini almaz ve bu hastada tanı zaten stereotaktik vakum yardımlı kor biyopsiyle konmuştur. Eksizyonu ertelemek, yüksek dereceli DCIS’te rezidüel hastalık ve olası eşlik eden invaziv odak riskini göz ardı eder. Cerrahi plan artık daha fazla tanısal kesiden çok lezyonun işaretlenerek tamamen çıkarılması ve cerrahi sınırların değerlendirilmesidir. Bu seçenek tedaviyi gereksiz yere geciktirir.",
        "Lumpektomi yapılacak her hastaya rutin aksiller lenf nodu diseksiyonu ekleme": "Aksiller lenf nodu diseksiyonu invaziv meme kanserinde seçilmiş nod pozitif durumlarda veya sentinel nod sonucuna göre gündeme gelebilir; saf DCIS’te lenfatik yayılım beklenmez. Lumpektomi yapılacak, klinik olarak nod negatif ve biyopside invazyon saptanmayan hastada rutin aksiller diseksiyon gereksiz lenfödem, omuz kısıtlılığı ve nöropatik ağrı riski taşır. Sentinel nod bile lumpektomi yapılan saf DCIS’te rutin değildir; mastektomi yapılacaksa sonradan sentinel yapılamayacağı için veya invazyon kuşkusu varsa düşünülür. Bu seçenek aksilla yönetimini gereğinden agresif hale getirir."
      }
    },
    "coreKnowledge": "DCIS’te tedavinin temeli cerrahi eksizyondur; meme koruyucu cerrahi yapılabiliyorsa negatif sınır hedeflenir ve radyoterapi lokal nüks riskini azaltır. Saf DCIS ve klinik nod negatif lumpektomi hastasında aksiller diseksiyon rutin değildir.",
    "examPearl": "Mikrokalsifikasyon + kor biyopside DCIS + kitle/nod yok = işaretli eksizyon; aksilla rutin değil.",
    "whyCorrect": "Doğru seçenek, nonpalpabl sınırlı DCIS’in lokal tedavisini ve aksillanın gereksiz agresif yönetiminden kaçınmayı birlikte içerir.",
    "optionComparison": "Seçenekler meme cerrahisi/onkolojik tedavi stratejileridir; kemoterapi-aksiller diseksiyon invaziv/nodal hastalığa, antibiyotik enfeksiyona, insizyonel biyopsi eski/eksik tanısal yaklaşıma, rutin aksiller diseksiyon ise gereksiz morbiditeye karşılık gelir.",
    "evidenceChain": [
      "Tarama mamografisinde pleomorfik mikrokalsifikasyon → nonpalpabl preinvaziv lezyon şüphesi.",
      "Kor biyopsi yüksek dereceli DCIS, invazyon yok → lokal cerrahi eksizyon hedefi.",
      "USG ve muayenede kitle/nod yok → rutin aksiller diseksiyon gereksiz.",
      "MRI’da sınırlı 1.9 cm alan ve multisentrik hastalık yok → meme koruyucu cerrahi uygun.",
      "Temiz sınır + radyoterapi → lokal kontrol stratejisi."
    ],
