  "hideExamSignal": true,
  "question": "Bu hasta için en uygun kaynak kontrolü ve tedavi yaklaşımı hangisidir?",
  "questionType": "source_control_management",
  "answerTarget": "pyogenic_liver_abscess_percutaneous_drainage",
  "diagnosis": {
    "correct": "İntravenöz antibiyotikle birlikte görüntüleme eşliğinde perkütan kateter drenajı",
    "options": [
      "Sadece oral antibiyotik verip iki hafta sonra poliklinik kontrolü",
      "İntravenöz antibiyotikle birlikte görüntüleme eşliğinde perkütan kateter drenajı",
      "Acil sağ hepatektomi ile apseli lobun rezeksiyonu",
      "Tanısal laparoskopi yapılmadan geniş spektrumlu tedaviyi erteleme",
      "Acil ERCP yapıp karaciğer içi koleksiyona müdahale etmeden izlem"
    ],
    "question": "Bu hasta için en uygun kaynak kontrolü ve tedavi yaklaşımı hangisidir?",
    "explanation": "Büyük, septalı ve sistemik inflamasyonla seyreden pyogenik karaciğer apsesinde tedavi yalnızca antibiyotik değildir; uygun intravenöz antibiyotikle birlikte görüntüleme eşliğinde perkütan drenaj kaynak kontrolünü sağlar. Hasta yaygın peritonit veya rezeksiyon gerektiren ek patoloji taşımadığı için ilk yaklaşım majör hepatektomi değil perkütan kateter drenajıdır.",
    "pearls": [
      "Büyük apse + sepsis bulgusu kaynak kontrolü gerektirir.",
      "Perkütan erişilebilir koleksiyonlarda drenaj cerrahi rezeksiyondan önce gelir.",
      "ERCP yalnızca eşlik eden biliyer obstrüksiyon/kolanjit baskınsa ana tedaviye eklenir."
    ],
    "optionFeedback": {
      "Sadece oral antibiyotik verip iki hafta sonra poliklinik kontrolü": "Sadece oral antibiyotik bu vaka için yetersizdir. Küçük, tek odaklı ve klinik olarak çok stabil bazı apselerde antibiyotikle izlem seçilebilir; ancak bu hastada 6.8 cm boyutunda, multiloküle görünümlü, septalı ve sistemik inflamasyon oluşturan bir koleksiyon vardır. Diyabet gibi risk faktörü de mevcuttur. Büyük apsede antibiyotik penetrasyonu ve boşalma tek başına güvenilir olmayacağı için kaynak kontrolü amacıyla görüntüleme eşliğinde drenaj gerekir.",
      "İntravenöz antibiyotikle birlikte görüntüleme eşliğinde perkütan kateter drenajı": "Bu seçenek doğrudur. Büyük pyogenik karaciğer apsesinde tedavinin temel mantığı uygun intravenöz antibiyotik ve kaynak kontrolüdür. Hastanın hemodinamik olarak resüsitasyona yanıt vermesi, yaygın peritonit olmaması ve koleksiyonun görüntüleme ile erişilebilir olması perkütan kateter drenajını uygun kılar. Drenaj materyali kültüre gönderilir; antibiyotik daha sonra kültür sonucuna göre daraltılır. Bu yaklaşım gereksiz büyük cerrahi rezeksiyondan kaçınırken sepsis kaynağını kontrol eder.",
      "Acil sağ hepatektomi ile apseli lobun rezeksiyonu": "Acil sağ hepatektomi pyogenik karaciğer apsesinde standart ilk yaklaşım değildir. Hepatik rezeksiyon; malignite şüphesi, drenaja yanıtsızlık, rüptür, yaygın nekrotik doku veya başka cerrahi patoloji gibi seçilmiş durumlarda gündeme gelebilir. Bu vakada kapsüllü, perkütan erişilebilir sağ lob koleksiyonu vardır ve hasta doğrudan büyük karaciğer rezeksiyonu gerektirecek kontrolsüz kanama veya tümör bulgusu taşımamaktadır. İlk basamak daha az invaziv kaynak kontrolüdür.",
      "Tanısal laparoskopi yapılmadan geniş spektrumlu tedaviyi erteleme": "Tanısal laparoskopi için tedaviyi ertelemek doğru değildir. Görüntüleme, apsenin boyutunu, yerini ve drenaja uygunluğunu göstermiştir; bu bilgi yönetim için yeterlidir. Cerrahi eksplorasyon, peritonit veya perkütan drenajın mümkün olmadığı/başarısız olduğu durumlarda düşünülür. Bu hastada gecikme sepsisin ilerlemesine neden olabilir; antibiyotik ve perkütan drenaj birlikte başlatılmalıdır.",
      "Acil ERCP yapıp karaciğer içi koleksiyona müdahale etmeden izlem": "ERCP, eşlik eden koledok taşı, kolanjit veya safra yolu obstrüksiyonu varsa tedavinin önemli bir parçası olabilir; ancak tek başına karaciğer parankimi içindeki büyük apseyi boşaltmaz. Bu vakada ana safra yolu belirgin geniş değil ve baskın problem sağ lobda büyük septalı koleksiyondur. ERCP ile koleksiyonun kaynak kontrolü sağlanamayacağı için apsenin kendisine görüntüleme eşliğinde drenaj gerekir. Safra yolu patolojisi sonradan kanıtlanırsa ek girişim planlanabilir."
    }
  },
  "shuffleOptions": false,
  "coreKnowledge": "Pyogenik karaciğer apsesinde karar, sadece ateş ve antibiyotik seçimi değil; koleksiyon boyutu, drenaja uygunluk, biliyer obstrüksiyon varlığı ve sepsis derecesinin birlikte okunmasıdır.",
  "examPearl": "Karaciğer apsesinde 5 cm üzeri veya septalı koleksiyon gördüğünde ‘antibiyotik + drenaj’ refleksini düşün; hepatektomi çoğu hastada ilk basamak değildir.",
  "whyCorrect": "Bu hastada 6.8 cm multiloküle koleksiyon, yüksek CRP/lökositoz ve diyabet vardır; kaynak kontrolü olmadan antibiyotik yetersiz kalabilir. Yaygın peritonit olmadığı ve koleksiyon perkütan erişilebilir olduğu için en uygun yaklaşım intravenöz antibiyotik ve görüntüleme eşliğinde kateter drenajıdır.",
  "optionComparison": "Doğru seçenek enfeksiyon tedavisi ile kaynak kontrolünü birlikte sağlar. Diğer seçenekler ya koleksiyonu boşaltmaz, ya tedaviyi geciktirir ya da ilk basamak için gereksiz büyük cerrahi önerir.",
  "evidenceChain": [
    "Dört gündür ateş-titreme → enfeksiyöz/septik klinik yük.",
    "6.8 cm septalı sağ lob koleksiyonu → büyük apse, drenaj gereksinimi.",
    "Yaygın peritonit ve serbest hava yok → perkütan yaklaşım için uygun stabilite.",
    "Ana safra kanalı 6 mm → baskın sorun acil ERCP değil intrahepatik koleksiyon.",
    "Diyabet ve yüksek CRP → yalnız antibiyotikle başarısızlık riski artar."
  ],
  "whyWrong": "Yanlış seçenekler büyük apsede kaynak kontrolünü sağlamaz, gereksiz majör karaciğer cerrahisine gider veya safra yolu girişimini intrahepatik koleksiyon drenajının yerine koyar.",
