  "question": "Bu hastada cerrahi plan öncesi en uygun ilk yönetim basamağı hangisidir?",
  "questionType": "perioperative_management",
  "answerTarget": "gastric_outlet_obstruction_metabolic_alkalosis_preop_resuscitation",
  "diagnosis": {
    "correct": "Nazogastrik dekompresyon, izotonik salin-potasyum replasmanı ve beslenme/stajlama sonrası cerrahi planlama",
    "options": [
      "Nazogastrik dekompresyon, izotonik salin-potasyum replasmanı ve beslenme/stajlama sonrası cerrahi planlama",
      "Elektrolitler düzeltilmeden aynı gün acil subtotal gastrektomi",
      "Hipokloremiyi artırmayacak şekilde sadece dekstrozlu hipotonik sıvı verme",
      "Kusmayı azaltmak için yüksek doz diüretik ve sıvı kısıtlaması başlama",
      "Oral katı gıdayı artırıp proton pompa inhibitörüyle taburcu etme"
    ],
    "question": "Bu hastada cerrahi plan öncesi en uygun ilk yönetim basamağı hangisidir?",
    "explanation": "Mide çıkış obstrüksiyonunda uzun süren kusma volüm, klor ve potasyum kaybına bağlı metabolik alkaloz yapar. Bu nedenle malignite şüphesi olsa bile perforasyon/aktif kanama yoksa güvenli cerrahi için önce nazogastrik dekompresyon, izotonik salin ve potasyum replasmanı, böbrek fonksiyonlarının düzeltilmesi, beslenme desteği ve evreleme gerekir.",
    "pearls": [
      "Kusma + düşük klor/potasyum + yüksek bikarbonat → hipokloremik hipokalemik metabolik alkaloz.",
      "Dolu ve distandü mide → aspirasyon riskini azaltmak için nazogastrik dekompresyon gerekir.",
      "Malignite şüphesi cerrahiyi planlatır; elektrolit bozukluğu ise cerrahi güvenliğini belirler."
    ],
    "optionFeedback": {
      "Nazogastrik dekompresyon, izotonik salin-potasyum replasmanı ve beslenme/stajlama sonrası cerrahi planlama": "Bu seçenek doğrudur. Mide çıkış obstrüksiyonunda tekrarlayan kusma hidrojen, klor ve potasyum kaybına bağlı hipokloremik-hipokalemik metabolik alkaloz oluşturur. Bu hasta dehidrate, kreatinini yükselmiş, kloru ve potasyumu düşük ve midesi belirgin distandüdür; doğrudan büyük cerrahiye almak aspirasyon, aritmi ve renal hipoperfüzyon riskini artırır. İlk basamak nazogastrik dekompresyon, izotonik salin ile klor replasmanı, potasyum düzeltme, böbrek perfüzyonunun toparlanması ve malignite evrelemesi/beslenme desteği sonrası uygun cerrahi planlamadır.",
      "Elektrolitler düzeltilmeden aynı gün acil subtotal gastrektomi": "Acil subtotal gastrektomi, perforasyon veya kontrolsüz kanama gibi bir acil yoksa elektrolitler düzeltilmeden yapılmamalıdır. Bu hastanın metabolik alkalozu, hipokalemisi ve prerenal azotemisi vardır; anestezi ve cerrahi öncesi bu bozukluklar düzeltilmezse ciddi aritmi, aspirasyon ve hemodinamik instabilite gelişebilir. Malignite olasılığı yüksek olsa bile mide çıkış obstrüksiyonunda preoperatif resüsitasyon ve dekompresyon tedavinin güvenli parçasıdır. Cerrahi planlama, stabilizasyon sonrası yapılır.",
      "Hipokloremiyi artırmayacak şekilde sadece dekstrozlu hipotonik sıvı verme": "Sadece dekstrozlu hipotonik sıvı bu hastanın temel elektrolit sorununu düzeltmez. Kusmaya bağlı alkalozda esas kayıp klor ve volümdür; böbreğin bikarbonat atabilmesi için klor ve etkili dolaşım hacmi gerekir. İzotonik salin bu nedenle fizyolojik olarak doğru sıvıdır; potasyum replasmanı da eşlik etmelidir. Hipotonik dekstrozlu sıvı, hiponatremi riskini artırabilir ve hipokloremik alkalozu yetersiz tedavi eder.",
      "Kusmayı azaltmak için yüksek doz diüretik ve sıvı kısıtlaması başlama": "Diüretik ve sıvı kısıtlaması bu vakadaki fizyopatolojiyi kötüleştirir. Hasta kusma ile volüm, klor ve potasyum kaybetmiştir; diüretikler potasyum kaybını artırır ve metabolik alkalozu derinleştirebilir. Mide distansiyonu ve aspirasyon riskini azaltmanın yolu diüretik değil nazogastrik dekompresyondur. Bu yaklaşım prerenal böbrek hasarını da kötüleştirebilir.",
      "Oral katı gıdayı artırıp proton pompa inhibitörüyle taburcu etme": "Oral katı gıdayı artırmak mide çıkış obstrüksiyonunda tercih edilmez. Hasta katıları kusmakta, kilo kaybetmekte ve endoskopide pilor/antrum düzeyinde lümeni daraltan kitle görülmektedir; taburculuk ve yalnız PPI tedavisi obstrüksiyonu çözmez. PPI ülser semptomlarını azaltabilir ancak mekanik çıkış darlığını, aspirasyon riskini ve metabolik bozukluğu düzeltmez. Bu hastada hastane koşullarında dekompresyon, sıvı-elektrolit düzeltme ve cerrahi/onkolojik plan gerekir."
    }
  },
  "shuffleOptions": false,
  "coreKnowledge": "Mide çıkış obstrüksiyonunda sınav tuzağı, kanser şüphesi görüldüğü anda ameliyata atlamaktır; önce hasta ameliyata hazırlanır.",
  "examPearl": "Projeksiyon: postprandiyal kusma + hipokloremik alkaloz + distandü mide = NG dekompresyon + salin/K replasmanı, sonra evreleme ve cerrahi.",
  "whyCorrect": "Hastada pilor/antrum düzeyinde mekanik darlık vardır fakat esas acil problem perforasyon değil kusmaya bağlı volüm-elektrolit bozukluğudur. Cerrahi güvenlik için önce mide boşaltılmalı, klor ve potasyum replase edilmeli, renal perfüzyon düzeltilmeli ve onkolojik planlama yapılmalıdır.",
  "optionComparison": "Doğru seçenek preoperatif fizyolojiyi düzeltir. Diğer seçenekler elektrolit bozukluğu varken cerrahiye acele eder, yanlış sıvı verir, volüm kaybını artırır veya mekanik obstrüksiyonu poliklinik tedavisine indirger.",
  "evidenceChain": [
    "Üç ay postprandiyal kusma ve kilo kaybı → kronik mide çıkış darlığı.",
    "Klor 82 mmol/L, K 2.8 mmol/L, HCO3− 38 mmol/L → kusmaya bağlı metabolik alkaloz.",
    "Üre/kreatinin yüksekliği ve kuru mukozalar → volüm kaybı ve prerenal stres.",
    "Endoskopide rezidü gıda ve dar pilor → NG dekompresyon ihtiyacı.",
    "BT’de serbest hava yok → önce stabilizasyon ve planlı cerrahi/onkolojik değerlendirme."
  ],
  "whyWrong": "Yanlış seçenekler metabolik alkaloz fizyolojisini göz ardı eder, aspirasyon riskini artırır veya mekanik darlığı yalnız semptom baskılama gibi ele alır.",
