  "question": "Bu hasta için en uygun cerrahi ve preoperatif güvenlik yaklaşımı hangisidir?",
  "questionType": "endocrine_surgery_management",
  "answerTarget": "medullary_thyroid_carcinoma_total_thyroidectomy_central_dissection",
  "diagnosis": {
    "correct": "Feokromositoma dışlandıktan sonra total tiroidektomi ve santral boyun diseksiyonu planlamak",
    "options": [
      "Sadece lobektomi yapıp radyoaktif iyot ablasyonu ile tamamlamak",
      "Antitiroid ilaç ve beta-bloker başlanıp nodülü altı ay sonra tekrar değerlendirmek",
      "Feokromositoma dışlandıktan sonra total tiroidektomi ve santral boyun diseksiyonu planlamak",
      "İnce iğne aspirasyonu malign geldiği için lateral boyun diseksiyonunu nod durumundan bağımsız rutin yapmak",
      "Kalsitonin yüksekliğini gastrit ilacı etkisi kabul edip cerrahi yerine yalnız izlem yapmak"
    ],
    "question": "Bu hasta için en uygun cerrahi ve preoperatif güvenlik yaklaşımı hangisidir?",
    "explanation": "Medüller tiroid karsinomu C hücre kökenlidir; kalsitonin ve CEA ile izlenir, radyoaktif iyot tedavisine dayanmaz. Cerrahi yaklaşım total tiroidektomi ve santral kompartman yönetimidir; MEN2 ilişkisi nedeniyle feokromositoma ameliyattan önce dışlanmalı, RET değerlendirmesi yapılmalıdır.",
    "pearls": [
      "Kalsitonin/CEA yüksekliği C hücre kökenli tümör yükünü destekler.",
      "Medüller kanserde radyoaktif iyot temel tedavi değildir.",
      "MEN2 olasılığı nedeniyle önce feokromositoma dışlanır, sonra tiroid cerrahisi yapılır."
    ],
    "optionFeedback": {
      "Sadece lobektomi yapıp radyoaktif iyot ablasyonu ile tamamlamak": "Lobektomi ve radyoaktif iyot ablasyonu medüller tiroid karsinomu için uygun temel yaklaşım değildir. Medüller tümör parafolliküler C hücrelerinden gelişir; iyot tutan foliküler hücre kökenli olmadığı için radyoaktif iyot tedavisi papiller/folliküler kanserlerdeki gibi etkili değildir. Ayrıca multifokalite ve herediter sendrom olasılığı nedeniyle cerrahi plan genellikle total tiroidektomidir. Lobektomi tek başına hem onkolojik kontrol hem de kalsitonin takibi açısından yetersiz kalabilir.",
      "Antitiroid ilaç ve beta-bloker başlanıp nodülü altı ay sonra tekrar değerlendirmek": "Antitiroid ilaç ve beta-bloker hipertiroidi tedavisinde kullanılır; bu hastada TSH normaldir ve sorun fonksiyonel tirotoksikoz değil malign sitoloji ve belirgin kalsitonin yüksekliğidir. Nodülü altı ay izlemek, medüller tiroid karsinomunda lenf nodu yayılımı ve herediter sendrom değerlendirmesini geciktirir. Beta-bloker yalnız semptomatik taşikardi gibi ayrı bir nedenle kısa süreli kullanılabilir; onkolojik cerrahi planın yerine geçmez.",
      "Feokromositoma dışlandıktan sonra total tiroidektomi ve santral boyun diseksiyonu planlamak": "Bu seçenek doğrudur. Medüller tiroid karsinomunda total tiroidektomi temel cerrahidir ve klinik olarak nod negatif hastada santral kompartman diseksiyonu sıklıkla planlanır. Ancak medüller kanser MEN2 ile ilişkili olabileceği için ameliyattan önce feokromositoma mutlaka dışlanmalıdır; aksi halde tiroid cerrahisi sırasında hipertansif kriz gelişebilir. RET mutasyon analizi ve kalsiyum/PTH değerlendirmesi de hasta ve ailesinin yönetimi için önemlidir. Lateral boyun diseksiyonu ise klinik/görüntüleme veya biyokimyasal olarak nodal tutulum varsa eklenir.",
      "İnce iğne aspirasyonu malign geldiği için lateral boyun diseksiyonunu nod durumundan bağımsız rutin yapmak": "Lateral boyun diseksiyonu nod durumundan bağımsız rutin yapılmaz. Medüller tiroid karsinomunda santral boyun yönetimi önemlidir; ancak lateral kompartmana cerrahi genişletme, USG, BT, FNA/kalsitonin yıkama veya belirgin biyokimyasal yük ile nodal hastalık şüphesine göre planlanır. Bu vakada lateral lenf nodu saptanmamıştır. Gereksiz lateral diseksiyon spinal aksesuar sinir, duktus torasikus, hipoglossal veya servikal duyu sinirleri açısından morbidite oluşturabilir.",
      "Kalsitonin yüksekliğini gastrit ilacı etkisi kabul edip cerrahi yerine yalnız izlem yapmak": "Proton pompa inhibitörü, kronik gastrit veya böbrek yetmezliği gibi durumlar kalsitonini hafif-orta düzeyde etkileyebilir; ancak bu hastada kalsitonin belirgin yüksek, CEA yüksek ve FNA medüller karsinomla uyumludur. Bunu ilaç etkisi kabul edip izlemek maligniteyi geciktirir. Medüller tiroid kanserinde kalsitonin hem tümör yükü hem de takip için kritik biyobelirteçtir; sitolojiyle birlikte değerlendirildiğinde cerrahi plan gerekir."
    }
  },
  "shuffleOptions": false,
  "coreKnowledge": "Medüller tiroid kanserinde sınavın altın ayrımı: papiller/folliküler gibi radyoaktif iyot düşünme; C hücresi, kalsitonin, RET ve feokromositoma güvenlik kontrolünü hatırla.",
  "examPearl": "Medüller tiroid kanserinde ‘önce feokromositoma dışla’ bilgisi cerrahi güvenlik açısından klasik ayırıcıdır.",
  "whyCorrect": "Bu hastada FNA medüller karsinomla uyumlu, kalsitonin ve CEA belirgin yüksek, lateral nodal hastalık gösterilmemiştir. Feokromositoma dışlandıktan sonra total tiroidektomi ve santral boyun diseksiyonu en uygun planı oluşturur.",
  "optionComparison": "Doğru seçenek tümör biyolojisini ve MEN2 güvenliğini birlikte ele alır. Yanlış seçenekler medüller kanseri foliküler hücre kökenli kanser gibi yönetir, nodal cerrahiyi gereksiz genişletir veya malign biyobelirteçleri izlemle geçiştirir.",
  "evidenceChain": [
    "Belirgin kalsitonin ve CEA yüksekliği → C hücre kökenli malignite lehine.",
    "İİAB medüller karsinomla uyumlu → tanısal cerrahi değil onkolojik cerrahi plan gerekir.",
    "Metanefrin normal → tiroid ameliyatı öncesi feokromositoma riski azaltılmış.",
    "Lateral boyunda patolojik nod yok → rutin lateral diseksiyon gereksiz.",
    "Medüller kanser iyot tutmaz → radyoaktif iyot ana tedavi değildir."
  ],
  "whyWrong": "Yanlış seçenekler medüller tiroid kanserinin C hücre biyolojisini, MEN2 güvenlik adımını veya boyun diseksiyonu endikasyonlarını yanlış yorumlar.",
