  "clinicalFocus": "Postoperatif yüksek debili enterokutan fistülde erken dönemde primer amaçların sepsis kontrolü, sıvı-elektrolit replasmanı, effluent/cilt kontrolü ve nütrisyonel destek olduğunu ayırt etme.",
  "learningTarget": "Fistül çıkış miktarı, elektrolit bozukluğu, hipoalbuminemi ve lokal cilt hasarını birlikte yorumlayarak erken cerrahi revizyon yerine stabilizasyon ve kontrollü gecikmiş cerrahi mantığını kurabilme.",
