    "historySummary": "Hasta on iki gün önce yapışıklığa bağlı ince bağırsak tıkanıklığı nedeniyle ameliyat edildiğini, son iki gündür orta hat yara yerinden sarı-yeşil renkli, kötü kokulu sıvı geldiğini anlatır. Pansumanı birkaç saat içinde tamamen ıslandığı için hemşireye haber vermiştir. Son 24 saatte belirgin halsizlik, susuzluk hissi ve ayağa kalkınca baş dönmesi eklenmiştir. Karın ağrısı ilk ameliyat günlerine göre daha azdır; ancak yara çevresinde yanma ve ciltte tahriş tarifler. Gaz çıkarabildiğini, az miktarda sulu dışkılama olduğunu ve ağızdan aldığı sıvıların çoğunu tolere edebildiğini söyler. Daha önce Crohn hastalığı, radyoterapi veya karın içi kanser öyküsü olmadığını belirtir."
