  "question": "Bu hastada endoskopik girişim sonrası tekrar kanama geliştiğine göre bir sonraki en uygun kaynak kontrol basamağı hangisidir?",
  "questionType": "peptic_ulcer_bleeding_failed_endoscopy_next_step",
  "answerTarget": "transcatheter_arterial_embolization_after_failed_endoscopic_hemostasis",
  "diagnosis": {
    "correct": "Anjiyografi ile gastroduodenal arter bölgesine yönelik transkateter arteriyel embolizasyon planlamak",
    "options": [
      "Yalnız yüksek doz proton pompa inhibitörü verip invaziv kaynak kontrolünü tamamen ertelemek",
      "Acil total gastrektomi yapmak",
      "Kolonoskopi hazırlığı başlatıp alt gastrointestinal kanama gibi izlemek",
      "Oral demir tedavisi düzenleyip poliklinik kontrolüne göndermek",
      "Anjiyografi ile gastroduodenal arter bölgesine yönelik transkateter arteriyel embolizasyon planlamak"
    ],
    "question": "Bu hastada endoskopik girişim sonrası tekrar kanama geliştiğine göre bir sonraki en uygun kaynak kontrol basamağı hangisidir?",
    "explanation": "Kanayan duodenal ülserde ilk basamak resüsitasyon, endoskopik hemostaz ve yüksek doz PPI tedavisidir. Ancak endoskopik tedaviye rağmen erken tekrar kanama, yüksek transfüzyon gereksinimi ve devam eden taşikardi varsa kaynak kontrolü yeniden planlanmalıdır. Hemodinamik olarak resüsitasyona yanıt veren hastada bir sonraki uygun basamak çoğu merkezde transkateter arteriyel embolizasyondur; cerrahi genellikle embolizasyon başarısız, ulaşılamaz veya hasta kontrolsüz şekilde instabil ise gündeme gelir.",
    "pearls": [
      "Kanayan peptik ülserde ilk kaynak kontrol endoskopidir.",
      "Endoskopi başarısızlığı sonrası stabil/yanıtlı hastada TAE önemli ikinci basamaktır.",
      "Cerrahi, kontrolsüz instabilite veya TAE başarısızlığı/ulaşılamaması durumunda öne çıkar."
    ],
    "optionFeedback": {
      "Yalnız yüksek doz proton pompa inhibitörü verip invaziv kaynak kontrolünü tamamen ertelemek": "Yüksek doz PPI kanayan peptik ülserde standart destek tedavisidir; pıhtı stabilizasyonuna ve tekrar kanama riskinin azalmasına katkı sağlar. Ancak bu hastada endoskopik tedaviye rağmen erken tekrar melena, taşikardi ve yüksek transfüzyon gereksinimi vardır. PPI tek başına aktif veya tekrarlayan arteriyel kaynaklı kanamayı durdurmak için yeterli değildir. İnvaziv kaynak kontrolünün ertelenmesi şok, daha fazla transfüzyon ve mortalite riskini artırır.",
      "Acil total gastrektomi yapmak": "Total gastrektomi bu klinik bağlam için aşırı ve anatomik olarak uygunsuz bir yaklaşımdır. Duodenal bulb arka duvarındaki kanamalar sıklıkla gastroduodenal arter çevresiyle ilişkilidir; cerrahi gerekirse hedefli duodenotomi, kanayan damarın kontrolü ve ülser cerrahisi prensipleri düşünülür. Ancak hasta resüsitasyona yanıtlıdır ve endoskopi sonrası bir sonraki organ koruyucu kaynak kontrol basamağı embolizasyondur. Total gastrektomi gereksiz morbidite yaratır ve doğru kanama anatomisini hedeflemez.",
      "Kolonoskopi hazırlığı başlatıp alt gastrointestinal kanama gibi izlemek": "Melena, üre yüksekliği, NSAİİ kullanımı ve endoskopide duodenal ülser bulgusu üst gastrointestinal kanama odağını ortaya koymuştur. Kolonoskopi alt kaynak şüphesi devam eden seçilmiş hastalarda kullanılabilir; ancak burada kanama odağı zaten yüksek riskli duodenal ülser olarak gösterilmiş ve endoskopik tedavi sonrası tekrar kanama gelişmiştir. Kolonoskopi hazırlığı kanama kontrolünü geciktirir ve hastayı ek sıvı-elektrolit yüküne sokabilir.",
      "Oral demir tedavisi düzenleyip poliklinik kontrolüne göndermek": "Oral demir kronik demir eksikliği anemisinde kullanılabilir; akut yüksek riskli gastrointestinal kanamada tedavi değildir. Hastanın hemoglobini 7.4 g/dL, tekrar melena ve taşikardisi vardır; bu hasta taburculuk veya sadece oral replasman adayı değildir. Önce hemodinami, kanama kontrolü ve yakın izlem sağlanmalıdır. Demir tedavisi ancak kanama kontrol edildikten ve etiyoloji yönetildikten sonra destek olarak gündeme gelebilir.",
      "Anjiyografi ile gastroduodenal arter bölgesine yönelik transkateter arteriyel embolizasyon planlamak": "Bu seçenek doğrudur. Duodenal arka duvar ülserinde endoskopik hemostaz girişimine rağmen erken tekrar kanama gelişmiş, hasta resüsitasyona kısmen yanıt vermiştir. Böyle bir hastada transkateter arteriyel embolizasyon kanayan arteriyel yatağı hedefleyerek cerrahi morbiditeyi azaltan uygun kaynak kontrol basamağıdır. İşlem sırasında gastroduodenal arter veya ilişkili dallar değerlendirilebilir. Embolizasyon başarısız olur, erişilemez veya hasta kontrolsüz instabil hale gelirse cerrahi kontrol gündeme gelir."
    }
  },
  "coreKnowledge": "Kanayan peptik ülserde endoskopik hemostaz başarısız veya tekrar kanama varsa resüsitasyona yanıtlı hastada transkateter arteriyel embolizasyon cerrahi öncesi güçlü bir kaynak kontrol seçeneğidir.",
  "examPearl": "Duodenal ülser kanaması + endoskopi sonrası tekrar kanama + resüsitasyona yanıtlı hasta = TAE düşün; kontrolsüz instabilite veya TAE başarısızlığı varsa cerrahi.",
  "whyCorrect": "Hastada endoskopide yüksek riskli duodenal ülser görülmüş ve tedaviye rağmen erken tekrar kanama gelişmiştir. Resüsitasyona yanıtlı olduğu için acil total cerrahi yerine anjiyografik embolizasyon en uygun sonraki kaynak kontrol basamağıdır.",
  "optionComparison": "Doğru seçenek kanayan arteriyel yatağı hedefler. Yanlış seçenekler yalnız medikal destekle aktif kanamayı bekletir, gereksiz radikal cerrahi yapar, kanama odağını yanlış sisteme taşır veya akut kanamayı poliklinik anemisi gibi ele alır.",
  "evidenceChain": [
    "Melena ve üre yüksekliği → üst gastrointestinal kanama paterni.",
    "Duodenal arka duvar ülseri ve görünür damar → yüksek riskli peptik ülser kanaması.",
    "Endoskopik hemostaz sonrası 4 saatte tekrar melena/taşikardi → endoskopik tedavi başarısızlığı veya erken tekrar kanama.",
    "Transfüzyon gereksinimi ve Hb 7.4 g/dL → klinik olarak önemli kanama yükü.",
    "Resüsitasyona yanıtlı hemodinami → anjiyografik kaynak kontrol için uygun pencere."
  ],
  "whyWrong": "Yanlış seçenekler tekrarlayan üst GIS kanamasında kaynak kontrolünü geciktirir, gereksiz radikal cerrahiye yönelir veya kanama odağını yanlış değerlendirme basamağına taşır.",
  "investigationLayerMeta": {
    "objective": "Kanayan peptik ülserde endoskopi başarısızlığı sonrası TAE ve cerrahi sıralamasını öğretme",
    "note": "V318 üst GIS kanama kaydı; önceki perforasyon, Boerhaave ve mide çıkış obstrüksiyonu kayıtlarından farklı olarak kanama kaynak kontrolünü hedefler."
  },
