  "question": "Uzak metastaz saptanmayan bu hasta için en uygun tamamlayıcı cerrahi yaklaşım hangisidir?",
  "questionType": "incidental_gallbladder_cancer_t2_completion_resection",
  "answerTarget": "completion_radical_cholecystectomy_liver_bed_resection_portal_lymphadenectomy",
  "diagnosis": {
    "correct": "Karaciğer yatağı segment IVb/V wedge veya sınırlı rezeksiyon ile bölgesel lenfadenektomi içeren tamamlayıcı radikal cerrahi planlamak",
    "options": [
      "Hiç ek tedavi vermeden yalnız yıllık ultrasonla izlemek",
      "Karaciğer yatağı segment IVb/V wedge veya sınırlı rezeksiyon ile bölgesel lenfadenektomi içeren tamamlayıcı radikal cerrahi planlamak",
      "Sistik kanal sınırı negatif olduğu için sadece ERCP ve sfinkterotomi yapmak",
      "Uzak metastaz yokken doğrudan palyatif kemoterapiye geçip cerrahiyi dışlamak",
      "Tüm hastalarda rutin pankreatikoduodenektomi yapmak"
    ],
    "question": "Uzak metastaz saptanmayan bu hasta için en uygun tamamlayıcı cerrahi yaklaşım hangisidir?",
    "explanation": "Basit kolesistektomi sonrası insidental safra kesesi adenokarsinomunda tedavi T evresine göre değişir. Lamina propria ile sınırlı çok erken hastalıkta basit kolesistektomi yeterli olabilir; ancak T2 düzeyinde perimüsküler bağ dokusuna invazyon varsa rezidüel hastalık ve nodal yayılım riski nedeniyle evreleme sonrası tamamlayıcı radikal cerrahi düşünülür. Tipik yaklaşım karaciğer yatağının segment IVb/V wedge veya sınırlı rezeksiyonu ile hepatoduodenal ligament bölgesel lenfadenektomisidir; safra yolu veya pankreatikoduodenektomi yalnız özel sınır/tutulum durumlarında gerekir.",
    "pearls": [
      "İnsidental safra kesesi kanserinde kararın ana ekseni T evresi ve metastaz taramasıdır.",
      "T2 ve üzeri uygun hastada tamamlayıcı karaciğer yatağı rezeksiyonu + bölgesel lenfadenektomi düşünülür.",
      "Negatif sistik kanal sınırı rutin ERCP veya pankreatikoduodenektomi gerektirmez."
    ],
    "optionFeedback": {
      "Hiç ek tedavi vermeden yalnız yıllık ultrasonla izlemek": "Yalnız izlem, lamina propria ile sınırlı çok erken ve tam çıkarılmış bazı olgularda düşünülebilir; ancak bu vakada tümör kas tabakasını aşarak perimüsküler bağ dokusuna uzanmıştır. Bu derinlik rezidüel mikroskopik hastalık ve bölgesel lenf nodu tutulumu riskini artırır. Sadece yıllık ultrasonla izlemek eksik evrelemeyi ve potansiyel küratif tamamlayıcı cerrahi şansını kaçırır. Hastanın uzak metastazı yok ve genel durumu iyi olduğu için onkolojik re-rezeksiyon değerlendirilmelidir.",
      "Karaciğer yatağı segment IVb/V wedge veya sınırlı rezeksiyon ile bölgesel lenfadenektomi içeren tamamlayıcı radikal cerrahi planlamak": "Bu seçenek doğrudur. Basit kolesistektomi patolojisinde T2 düzeyinde insidental safra kesesi adenokarsinomu saptanmış, sistik kanal sınırı negatif ve uzak metastaz yoktur. İlk ameliyatta lenf nodu örneklenmediği için evreleme eksiktir. Uygun hastada tamamlayıcı radikal cerrahi, karaciğer yatağında olası rezidüel mikroskopik hastalığı ve bölgesel lenf nodu yayılımını hedefler. Segment IVb/V wedge veya sınırlı karaciğer yatağı rezeksiyonu ile hepatoduodenal ligament lenfadenektomisi bu nedenle doğru onkolojik yaklaşımdır.",
      "Sistik kanal sınırı negatif olduğu için sadece ERCP ve sfinkterotomi yapmak": "ERCP ve sfinkterotomi safra yolu taşı, kolanjit veya bazı biliyer kaçak/obstrüksiyon durumlarında anlamlıdır; T2 safra kesesi kanserinin onkolojik tedavisi değildir. Sistik kanal sınırının negatif olması iyi bir bulgudur, ancak perimüsküler invazyon ve lenf nodu riski ortadan kalkmaz. Bu nedenle yalnız ERCP yapmak karaciğer yatağındaki mikroskopik hastalığı ve bölgesel nodları tedavi etmez. ERCP ancak klinik olarak biliyer obstrüksiyon veya kaçak gibi ayrı bir problem varsa gündeme gelir.",
      "Uzak metastaz yokken doğrudan palyatif kemoterapiye geçip cerrahiyi dışlamak": "Palyatif kemoterapi uzak metastatik, rezeksiyona uygun olmayan veya ciddi performans sorunu olan hastalarda ön plana çıkar. Bu hastada evreleme BT’sinde uzak metastaz yok, genel durum iyi ve patoloji potansiyel küratif tamamlayıcı cerrahi gerektiren T2 hastalığı göstermektedir. Cerrahiyi tamamen dışlamak, küratif niyetli tedavi fırsatını kaçırır. Adjuvan tedavi gereksinimi nihai patoloji ve nodal evreye göre ayrıca tartışılabilir; ancak ilk doğru adım uygun hastada re-rezeksiyon değerlendirmesidir.",
      "Tüm hastalarda rutin pankreatikoduodenektomi yapmak": "Pankreatikoduodenektomi safra kesesi kanserinde rutin tamamlayıcı işlem değildir ve ciddi morbidite taşır. Distal safra yolu, pankreas veya duodenum invazyonu, pozitif distal safra yolu sınırı gibi özel durumlar yoksa standart yaklaşım karaciğer yatağı rezeksiyonu ve bölgesel lenfadenektomidir. Bu vakada sistik kanal sınırı negatif, görüntülemede pankreatikoduodenal tutulum yoktur. Her hastaya Whipple yapmak onkolojik hedefi aşan, gereksiz radikal bir yaklaşımdır."
    }
  },
  "coreKnowledge": "İnsidental safra kesesi kanserinde Tis/T1a gibi çok erken evrelerde basit kolesistektomi yeterli olabilir; T2 düzeyinde uygun hastada tamamlayıcı karaciğer yatağı rezeksiyonu ve bölgesel lenfadenektomi gerekir.",
  "examPearl": "Kolesistektomi sonrası patolojide T2 safra kesesi kanseri + metastaz yok = tamamlayıcı radikal rezeksiyon ve lenfadenektomi düşün.",
  "whyCorrect": "Bu hastada tümör perimüsküler bağ dokusuna uzanmış, uzak metastaz saptanmamış ve ilk ameliyatta lenf nodu evrelemesi yapılmamıştır. Bu nedenle yalnız izlem veya ERCP değil, karaciğer yatağı rezeksiyonu ve bölgesel lenfadenektomi içeren tamamlayıcı cerrahi gerekir.",
  "optionComparison": "Doğru seçenek potansiyel rezidüel karaciğer yatağı hastalığını ve nodal evrelemeyi hedefler. Yanlış seçenekler ya kanseri aşırı erken evre gibi izler, biliyer endoskopik işlemi onkolojik tedavi sanır, küratif cerrahi şansını gereksiz palyatif tedaviyle dışlar veya aşırı radikal pankreatikoduodenektomi önerir.",
  "evidenceChain": [
    "Patolojide adenokarsinom → basit taş hastalığı dışında onkolojik problem.",
    "Perimüsküler bağ dokusuna invazyon → T2 düzeyi ve rezidüel/nodal risk.",
    "Sistik kanal sınırı negatif → rutin safra yolu rezeksiyonu/ERCP gerektiren veri yok.",
    "BT’de uzak metastaz yok → küratif niyetli tamamlayıcı cerrahi için uygun evreleme penceresi.",
    "İlk ameliyatta lenf nodu örneklenmemiş → bölgesel lenfadenektomiyle evreleme ve tedavi gereksinimi."
  ],
  "whyWrong": "Yanlış seçenekler T2 insidental safra kesesi kanserinin onkolojik re-rezeksiyon ihtiyacını ya küçümser ya da gereksiz endoskopik/palyatif/aşırı radikal işlemlerle tedavi hedefini bozar.",
  "investigationLayerMeta": {
    "objective": "İnsidental T2 safra kesesi kanserinde tamamlayıcı radikal cerrahi endikasyonunu öğretme",
    "note": "V318 hepatobiliyer onkoloji kaydı; önceki kolesistit, kolanjit, safra kaçağı ve karaciğer apsesi kayıtlarından farklı olarak insidental malignite re-rezeksiyon kararını hedefler."
  },
