  "optionComparison": "Doğru seçenek ansları korur ve kesin fasyal onarımı sağlar. Yanlış seçenekler ya olayı yüzeyel yara kabul eder, ya yatak başı güvensiz kapama önerir ya da görüntüleme/elektif planlama ile acil korumayı geciktirir.",
