  "stem": "Hasta son altı haftada sol memesinin giderek şiştiğini, cildin kızarıp kalınlaştığını ve sütyeninin dar gelmeye başladığını anlatır. Başlangıçta enfeksiyon sandığı için evde ağrı kesici kullanmış ancak kızarıklık gerilememiştir. Emzirme, yakın dönem travma veya meme başından pürülan akıntı tariflemez. Son iki haftadır koltuk altında sertlik fark ettiğini ve sol memede ağırlık hissinin arttığını söyler. Ailesinde menopoz sonrası meme kanseri öyküsü vardır; ateşi olmadığını belirtir.",
