  "question": "Bu hasta için en uygun tedavi sıralaması aşağıdakilerden hangisidir?",
  "questionType": "treatmentSequence",
  "answerTarget": "Yaygın cilt tutulumlu meme kanserinde doğru multimodal tedavi sırası",
  "diagnosis": {
    "correct": "Doku tanısı ve evreleme sonrası neoadjuvan sistemik tedavi, ardından cerrahi ve radyoterapi içeren multimodal plan yapmak",
    "options": [
      "Doku tanısı ve evreleme sonrası neoadjuvan sistemik tedavi, ardından cerrahi ve radyoterapi içeren multimodal plan yapmak",
      "Aynı gün lokal anesteziyle kitle eksizyonu yapıp patoloji sonucuna göre izlemek",
      "İki hafta oral antibiyotik verip eritem geçmezse mamografiyi tekrarlamak",
      "Sadece sentinel lenf nodu biyopsisi yapıp memeye işlem uygulamamak",
      "Primer meme koruyucu cerrahi ve aynı seansta parsiyel meme ışınlaması planlamak"
    ],
    "question": "Bu hasta için en uygun tedavi sıralaması aşağıdakilerden hangisidir?",
    "explanation": "Yaygın eritem, ödem, peau d’orange görünümü ve dermal lenfatik tümör embolileri lokal cerrahiyle başlanmaması gereken agresif meme kanseri paternidir. Doku tanısı ve uzak metastaz taraması sonrası tedavi sistemik olarak başlar; neoadjuvan tedavi sonrası cerrahi ve radyoterapi planlanır. Antibiyotikle beklemek veya primer meme koruyucu cerrahi yapmak onkolojik sırayı bozar.",
    "pearls": [
      "Yaygın peau d’orange ve dermal lenfatik tümör embolileri lokal mastitten ayrılır.",
      "Tedavi başlangıcı genellikle neoadjuvan sistemik tedavidir; cerrahi ilk adım değildir.",
      "Aksiller nod ve biyolojik alt tip sistemik tedavi planında belirleyicidir."
    ],
    "optionFeedback": {
      "Doku tanısı ve evreleme sonrası neoadjuvan sistemik tedavi, ardından cerrahi ve radyoterapi içeren multimodal plan yapmak": "Bu seçenek vakadaki klinik ve patolojik zemine en uygun multimodal yaklaşımdır. Hızlı gelişen yaygın eritem, ödem, peau d’orange görünümü, aksiller nod ve biyopside invaziv karsinom ile dermal lenfatik tümör embolileri lokal tedaviyle başlanmaması gereken agresif bir tabloyu gösterir. İlk basamak yalnız cerrahi değil; sistemik hastalık riski nedeniyle neoadjuvan sistemik tedavi ve uygun evrelemedir. Yanıt sonrası mastektomi/aksiller yaklaşım ve radyoterapi planı multidisipliner yapılır.",
      "Aynı gün lokal anesteziyle kitle eksizyonu yapıp patoloji sonucuna göre izlemek": "Lokal kitle eksizyonu, sınırlı iyi seçilmiş meme lezyonlarında tanısal veya terapötik rol oynayabilir; ancak yaygın cilt tutulumu ve aksiller nodla seyreden bu klinikte yetersiz kalır. Sorun yalnız çıkarılabilir küçük bir kitle değil, dermal lenfatik ağ üzerinden yaygın cilt tutulumudur. Aynı gün lokal eksizyon tümör biyolojisini, nodal evrelemeyi ve sistemik tedavi gereksinimini karşılamaz. Bu yaklaşım tedaviyi parçalara böler ve doğru onkolojik sırayı bozar.",
      "İki hafta oral antibiyotik verip eritem geçmezse mamografiyi tekrarlamak": "Mastit emzirme döneminde ağrı, ateş ve laktasyon öyküsüyle gelebilir; kısa süreli antibiyotik yanıtı beklenebilir. Ancak bu hasta emzirmiyor, yakınma haftalar içinde ilerlemiş, peau d’orange görünümü ve sert aksiller nod vardır. Biyopsi invaziv karsinom ve dermal lenfatik tümör embolilerini göstermektedir. Antibiyotikle beklemek tanı konmuş malign süreçte gecikmeye yol açar.",
      "Sadece sentinel lenf nodu biyopsisi yapıp memeye işlem uygulamamak": "Sentinel lenf nodu biyopsisi erken evre klinik nod negatif meme kanserinde aksiller evreleme için kullanılır. Bu vakada aksiller nod palpabl ve görüntülemede şüpheli; ayrıca yaygın cilt tutulumu vardır. Sadece sentinel işlem yapmak primer tümörü, sistemik tedavi ihtiyacını ve radyoterapi gereksinimini çözmez. Aksiller değerlendirme neoadjuvan tedavi ve cerrahi planın parçası olarak daha kapsamlı ele alınır.",
      "Primer meme koruyucu cerrahi ve aynı seansta parsiyel meme ışınlaması planlamak": "Meme koruyucu cerrahi erken evre, sınırlı tümörlerde ve uygun meme/tümör oranında etkili olabilir. Bu hastada yaygın cilt eritemi, ödem ve dermal lenfatik tutulum vardır; parsiyel meme ışınlaması da bu biyoloji için yetersiz lokal tedavidir. Tedavi lokal eksizyonla başlamaz; sistemik tedavi önceliklidir. Multimodal yaklaşım olmadan primer konservatif cerrahi onkolojik kontrolü sağlamaz."
    }
  },
  "coreKnowledge": "Yaygın meme cilt tutulumu olan agresif meme kanserinde tanı-evreleme sonrası neoadjuvan sistemik tedavi, ardından cerrahi ve radyoterapi içeren multimodal yaklaşım esastır.",
  "examPearl": "Emzirmeyen hastada hızla ilerleyen meme eritemi + peau d’orange + aksiller nod + dermal lenfatik tümör embolisi = antibiyotikle bekleme değil, multimodal onkolojik tedavi.",
  "whyCorrect": "Bu hastada ateş ve apse koleksiyonu yokken yaygın cilt ödemi, aksiller nod ve biyopsiyle doğrulanmış malign dermal lenfatik tutulum vardır. Bu nedenle lokal cerrahi veya antibiyotik değil, evreleme sonrası sistemik tedaviyle başlayan onkolojik plan gerekir.",
  "optionComparison": "Doğru seçenek sistemik hastalık riskini ve lokal cilt tutulumu biyolojisini birlikte ele alır. Yanlış seçenekler ya enfeksiyon gibi bekler, ya erken evre meme kanseri gibi sınırlı cerrahi önerir ya da aksillayı tek başına tedavi hedefi zanneder.",
  "evidenceChain": [
    "Altı haftada hızlı meme şişliği ve kızarıklık → agresif lokal süreç.",
    "Peau d’orange ve yaygın cilt kalınlaşması → dermal lenfatik tıkanma paternine işaret eder.",
    "Apse koleksiyonu olmaması ve ateş yokluğu → basit mastit olasılığını zayıflatır.",
    "Kor biyopside invaziv karsinom → malign doku tanısı.",
    "Dermal lenfatik tümör embolileri → multimodal tedavi gerektiren yaygın cilt tutulumu."
  ],
  "whyWrong": "Yanlış seçenekler hastalığı ya lokal küçük kitle ya da enfeksiyon gibi ele alır; bu da sistemik tedavi ve doğru evreleme basamaklarını geciktirir.",
  "investigationLayerMeta": {
    "objective": "Yaygın cilt tutulumlu meme kanserinde neoadjuvan sistemik tedavi ve multimodal yaklaşımı öğretme",
    "note": "V319 yeni Genel Cerrahi kaydı; mevcut erken evre meme kitlesi, DCIS ve laktasyonel apse kayıtlarından farklı olarak yaygın cilt tutulumu ve tedavi sırasını hedefler."
  },
