  "question": "Bu hasta için en uygun genel cerrahi tedavi yaklaşımı aşağıdakilerden hangisidir?",
  "questionType": "treatment",
  "answerTarget": "Semptomatik büyük karaciğer hidatik kistinde güvenli tedavi yaklaşımı",
  "diagnosis": {
    "correct": "Albendazol hazırlığıyla birlikte skolisidal önlem alınarak uygun perkütan veya cerrahi kist tedavisi planlamak",
    "options": [
      "Yalnız yıllık ultrason izlemi yapmak ve antiparaziter tedavi vermemek",
      "Tanısal amaçlı kontrolsüz ince iğne aspirasyonu yapıp sıvıyı kültüre göndermek",
      "Acil total hepatektomi ve transplantasyon listesine almak",
      "Albendazol hazırlığıyla birlikte skolisidal önlem alınarak uygun perkütan veya cerrahi kist tedavisi planlamak",
      "Safra kesesi taşı kabul edip yalnız laparoskopik kolesistektomi yapmak"
    ],
    "question": "Bu hasta için en uygun genel cerrahi tedavi yaklaşımı aşağıdakilerden hangisidir?",
    "explanation": "Büyük, semptomatik ve kız veziküller içeren karaciğer kistinde basit kist veya safra taşı gibi davranılmaz. Tedavi planında parazitik içeriğin yayılım ve anafilaksi riski dikkate alınır; albendazol hazırlığı, skolisidal önlemler ve kistin anatomisine göre perkütan veya cerrahi yöntem seçilir. Kontrolsüz aspirasyon risklidir.",
    "pearls": [
      "Kız veziküllü büyük karaciğer kisti paraziter kist lehinedir.",
      "Kontrolsüz aspirasyon yayılım ve alerjik reaksiyon riski taşır.",
      "Tedavi yöntemi kistin tipi, safra yolu ilişkisi, boyutu ve merkezin deneyimine göre seçilir."
    ],
    "optionFeedback": {
      "Yalnız yıllık ultrason izlemi yapmak ve antiparaziter tedavi vermemek": "İzlem küçük, asemptomatik ve inaktif görünümlü bazı kistik lezyonlarda düşünülebilir; ancak bu hastada 8 cm boyut, sağ üst kadran dolgunluğu ve görüntülemede kız veziküller vardır. Büyük ve semptomatik kistte rüptür, enfeksiyon, safra yolu ilişkisi ve bası semptomları açısından aktif tedavi planı gerekir. Antiparaziter hazırlık olmadan yalnız izlem, canlı içerik ve yayılım riskini göz ardı eder. Bu nedenle yıllık izlem bu vaka için yeterli yaklaşım değildir.",
      "Tanısal amaçlı kontrolsüz ince iğne aspirasyonu yapıp sıvıyı kültüre göndermek": "Kontrolsüz tanısal aspirasyon bu klinikte riskli bir davranıştır. Kistik içerik canlı parazitik materyal içerebilir; uygun hazırlık ve skolisidal önlem olmadan delinmesi alerjik reaksiyon, yayılım ve sekonder ekinokokkoz riski taşır. Perkütan tedavi yapılacaksa bu işlem tanısal merakla değil, uygun hasta seçimi, albendazol, görüntüleme rehberliği ve skolisidal protokol içinde yapılır. Bu nedenle basit ince iğne aspirasyonu doğru yaklaşım değildir.",
      "Acil total hepatektomi ve transplantasyon listesine almak": "Transplantasyon veya total hepatektomi, lokalize karaciğer kisti için orantısız ve gerçekçi olmayan bir yaklaşımdır. Bu hastada karaciğer fonksiyonları korunmuş, portal hipertansiyon veya yaygın geri dönüşsüz karaciğer hastalığı yoktur. Kist segment VII’de lokalizedir ve tedavi hedefi kist içeriğini güvenli biçimde kontrol etmek, yayılımı önlemek ve semptomu gidermektir. Radikal organ kaybı gerektiren bir durum sunulmamıştır.",
      "Albendazol hazırlığıyla birlikte skolisidal önlem alınarak uygun perkütan veya cerrahi kist tedavisi planlamak": "Bu seçenek vakadaki bulgularla en uyumlu tedavi mantığını verir. Büyük, semptomatik ve kız veziküller içeren karaciğer kistinde tedavi planlanırken parazitik içerik yayılımı ve anafilaksi riski düşünülür. Albendazol hazırlığı, işlem sırasında skolisidal önlem ve kistin anatomisine göre perkütan veya cerrahi yaklaşım seçimi gerekir. Safra yolu ilişkisi, yüzeyelleşme, çok bölmeli yapı ve merkez deneyimi yöntemi belirler; temel ilke kontrolsüz aspirasyondan kaçınmaktır.",
      "Safra kesesi taşı kabul edip yalnız laparoskopik kolesistektomi yapmak": "Sağ üst kadran ağrısı safra kesesi taşında görülebilir; ancak bu hastada ultrasonografide safra kesesi duvar kalınlaşması, taş veya perikolesistik sıvı değil, karaciğer parankiminde kız veziküller içeren büyük kistik lezyon vardır. Yalnız kolesistektomi kistin kaynağını tedavi etmez. Gereksiz safra kesesi ameliyatı gerçek lezyonu bırakır ve hastayı ek riskle karşılaştırır. Tedavi kistin özelliklerine göre planlanmalıdır."
    }
  },
  "coreKnowledge": "Semptomatik büyük karaciğer hidatik kistinde temel ilke; antiparaziter hazırlık, skolisidal güvenlik ve uygun perkütan/cerrahi kaynak kontrolüdür, kontrolsüz aspirasyondan kaçınılır.",
  "examPearl": "Karaciğerde kız veziküller + kırsal/hayvan teması + büyük semptomatik kist = basit aspirasyon değil, albendazol ve kontrollü kist tedavisi.",
  "whyCorrect": "Bu hastada safra taşı veya kolanjit bulgusu yoktur; görüntüleme büyük, kompleks, kız veziküller içeren karaciğer kistini göstermektedir. Bu nedenle kontrollü antiparaziter ve girişimsel/cerrahi plan gerekir.",
  "optionComparison": "Doğru seçenek kistin biyolojik içeriğini ve işlem riskini hesaba katar. Yanlış seçenekler ya aktif kisti yalnız izler, ya kontrolsüz aspirasyonla yayılım riski yaratır, ya gereksiz aşırı cerrahi önerir ya da safra kesesi patolojisi gibi yanlış hedefe yönelir.",
  "evidenceChain": [
    "Kırsal ve küçükbaş hayvan teması → paraziter kist olasılığını artıran epidemiyolojik veri.",
    "82 × 71 mm boyut ve erken doyma → semptomatik büyük lezyon.",
    "Kız vezikül benzeri iç yapılar → basit kistten ayrılan kompleks kist paterni.",
    "Normal bilirubin ve safra yolu genişliği olmaması → primer kolanjit/obstrüksiyon tablosu yok.",
    "Serbest sıvı olmaması → acil rüptür değil, planlı kontrollü tedavi penceresi."
  ],
  "whyWrong": "Yanlış seçenekler kistin parazitik ve kompleks doğasını ya hafife alır ya da kontrolsüz girişimle yayılım/anafilaksi riskini artırır.",
  "investigationLayerMeta": {
    "objective": "Karaciğer hidatik kistinde görüntüleme paternine göre güvenli tedavi planını öğretme",
    "note": "V319 yeni Genel Cerrahi kaydı; mevcut kolesistit, kolanjit, karaciğer apsesi ve safra kesesi kanseri kayıtlarından farklı olarak paraziter kist güvenliğini hedefler."
  },
