  "question": "Bu hastada cerrahiye giden doğru karar süreci aşağıdakilerden hangisidir?",
  "questionType": "surgicalDecision",
  "answerTarget": "Primer aldosteronizmde adrenalektomi öncesi doğrulama ve lateralizasyon",
  "diagnosis": {
    "correct": "Biyokimyasal doğrulama ve lateralizasyon değerlendirmesi sonrası tek taraflı kaynak gösterilirse laparoskopik adrenalektomi planlamak",
    "options": [
      "Hipokalemi düzelmeden doğrudan laparoskopik adrenalektomi yapmak",
      "Adrenal kitleyi metastaz kabul edip primer tümör aramadan palyatif kemoterapi başlamak",
      "Biyokimyasal doğrulama ve lateralizasyon değerlendirmesi sonrası tek taraflı kaynak gösterilirse laparoskopik adrenalektomi planlamak",
      "Tüm hastalarda bilateral adrenalektomi yapıp ömür boyu steroid replasmanı başlamak",
      "Sadece potasyum replasmanı verip hipertansiyon kontrolünü değerlendirmeden izlemek"
    ],
    "question": "Bu hastada cerrahiye giden doğru karar süreci aşağıdakilerden hangisidir?",
    "explanation": "Dirençli hipertansiyon, hipokalemi, metabolik alkaloz, aldosteron yüksekliği ve baskılanmış renin primer aldosteronizm açısından güçlü bir patern oluşturur. Ancak BT’de tek taraflı nodül görülmesi her zaman fonksiyonel kaynağı kesinleştirmez. Uygun biyokimyasal doğrulama, hipokalemi/tansiyon stabilizasyonu ve lateralizasyon sonrası tek taraflı hastalık gösterilirse laparoskopik adrenalektomi planlanır.",
    "pearls": [
      "Primer aldosteronizmde tarama: yüksek aldosteron, baskılanmış renin, yüksek oran.",
      "Adrenal BT anatomiyi gösterir; lateralizasyon için seçilmiş hastada adrenal ven örneklemesi gerekebilir.",
      "Unilateral hastalık cerrahi, bilateral hiperplazi çoğunlukla medikal tedavi yönünde ele alınır."
    ],
    "optionFeedback": {
      "Hipokalemi düzelmeden doğrudan laparoskopik adrenalektomi yapmak": "Adrenal görüntülemede nodül görülmesi tek başına ameliyat kararı için yeterli olmayabilir. Özellikle erişkin hastalarda nonfonksiyonel insidentalomalar ve karşı taraf mikronodüler hastalık ayırıcıda yer alır. Hipokalemi düzeltilmeden ve hormonal kaynak netleştirilmeden cerrahiye gitmek perioperatif aritmi ve yanlış taraf cerrahisi riskini artırır. Önce biyokimyasal doğrulama, medikal stabilizasyon ve lateralizasyon gerekir.",
      "Adrenal kitleyi metastaz kabul edip primer tümör aramadan palyatif kemoterapi başlamak": "Adrenal kitleler metastaz olabilir; ancak bu hastada dirençli hipertansiyon, baskılanmış renin, yüksek aldosteron-renin oranı ve hipokalemi mineralokortikoid fazlalığını düşündüren fonksiyonel bir paterndir. Primer tümör aramadan palyatif kemoterapi başlamak hem klinik biyokimyayı yok sayar hem de tedavi edilebilir hipertansiyon nedenini kaçırır. Malignite şüphesi boyut, görüntüleme karakteri ve hormon profiline göre ayrıca değerlendirilir. Bu vakada ana karar endokrin cerrahiye uygun lateralizasyon sürecidir.",
      "Biyokimyasal doğrulama ve lateralizasyon değerlendirmesi sonrası tek taraflı kaynak gösterilirse laparoskopik adrenalektomi planlamak": "Bu seçenek vakadaki doğru cerrahi planlama mantığını verir. Dirençli hipertansiyon, spontan hipokalemi, baskılanmış renin ve yüksek aldosteron-renin oranı primer aldosteronizm olasılığını güçlendirir. Cerrahi kür hedefleniyorsa kaynak gerçekten tek taraflı mı gösterilmelidir; uygun doğrulama ve lateralizasyon sonrası unilateral hastalıkta laparoskopik adrenalektomi planlanır. Cerrahiye kadar potasyum düzeltilir ve mineralokortikoid reseptör antagonistiyle tansiyon kontrolü sağlanabilir.",
      "Tüm hastalarda bilateral adrenalektomi yapıp ömür boyu steroid replasmanı başlamak": "Bilateral adrenalektomi primer aldosteronizmin rutin tedavisi değildir ve hastayı gereksiz adrenal yetmezlik ile ömür boyu glukokortikoid-mineralokortikoid replasmanına bağımlı bırakır. Bilateral adrenal hiperplazide çoğu zaman medikal tedavi tercih edilir; unilateral aldosteron üreten adenomda ise tek taraflı adrenalektomi yeterli olabilir. Bu vakada lateralizasyon yapılmadan iki adrenal bezin çıkarılması aşırı ve zararlı bir yaklaşımdır.",
      "Sadece potasyum replasmanı verip hipertansiyon kontrolünü değerlendirmeden izlemek": "Potasyum replasmanı akut hipokalemiyi düzeltmek için gerekir; fakat altta yatan hormonal mekanizmayı tedavi etmez. Hastada uzun süredir dirençli hipertansiyon ve aldosteron-renin paterninde belirgin bozulma vardır. Sadece potasyum vermek hipertansiyon, kardiyovasküler risk ve tekrarlayan hipokalemi döngüsünü sürdürür. Endokrin değerlendirme ve uygun hastada cerrahi/medikal hedef tedavi planı yapılmalıdır."
    }
  },
  "coreKnowledge": "Fonksiyonel adrenal cerrahide görüntüleme bulgusu biyokimyasal doğrulama ve lateralizasyonla birleştirilmelidir; unilateral primer aldosteronizmde laparoskopik adrenalektomi kür sağlayabilir.",
  "examPearl": "Dirençli hipertansiyon + hipokalemi + düşük renin/yüksek aldosteron = primer aldosteronizm düşün; BT nodülü görüp hemen ameliyat etme, lateralizasyonu doğrula.",
  "whyCorrect": "Bu hastada hipokalemik metabolik alkaloz ve aldosteron-renin oranı otonom aldosteron üretimini desteklemektedir. Sol adrenal nodül olası kaynak olsa da cerrahi plan için hormonal doğrulama ve lateralizasyon gereklidir.",
  "optionComparison": "Doğru seçenek endokrin cerrahide fizyoloji-anatomi eşleşmesini kurar. Yanlış seçenekler ya görüntülemeye aşırı güvenerek erken cerrahiye gider, ya kitleyi yanlışlıkla metastaz gibi ele alır, ya aşırı bilateral cerrahi önerir ya da yalnız potasyum replasmanıyla altta yatan nedeni bırakır.",
  "evidenceChain": [
    "Üç ilaçla kontrolsüz hipertansiyon → sekonder hipertansiyon araştırma gereği.",
    "Potasyum 2.8 mmol/L ve bikarbonat yüksekliği → mineralokortikoid etkisine bağlı renal kayıp paterni.",
    "Aldosteron yüksek, renin baskılı → otonom aldosteron üretimi lehine.",
    "BT’de 18 mm sol adrenal nodül → anatomik hedef olabilir ama tek başına kesin taraf kanıtı değildir.",
    "Kriz şeklinde terleme/baş ağrısı olmaması → feokromositoma daha geri planda, yine de adrenal cerrahi öncesi hormon profili bütüncül değerlendirilir."
  ],
  "whyWrong": "Yanlış seçenekler primer aldosteronizmin cerrahiye uygun alt tipini belirlemeden ya fazla hızlı ya fazla radikal ya da yetersiz tedavi planlar.",
