  "question": "Bu hasta için en uygun cerrahi/tedavi yaklaşımı aşağıdakilerden hangisidir?",
  "questionType": "treatment",
  "answerTarget": "Safra taşı ilişkili mekanik ince barsak obstrüksiyonunda enterolitotomi önceliği",
  "diagnosis": {
    "correct": "Sıvı-elektrolit resüsitasyonu sonrası enterotomi ile tıkayıcı taşı çıkarmak, fistül cerrahisini seçilmiş hastaya ertelemek",
    "options": [
      "Kolonoskopik dekompresyon yapıp rektal tüp yerleştirmek",
      "Yalnızca nazogastrik dekompresyonla 72 saat konservatif izlemek",
      "Laparoskopik kolesistektomi ve koledok eksplorasyonunu tek başına yapmak",
      "Sıvı-elektrolit resüsitasyonu sonrası enterotomi ile tıkayıcı taşı çıkarmak, fistül cerrahisini seçilmiş hastaya ertelemek",
      "Acil ERCP ile distal koledoktan taşı çıkarmak"
    ],
    "question": "Bu hasta için en uygun cerrahi/tedavi yaklaşımı aşağıdakilerden hangisidir?",
    "explanation": "Yaşlı, komorbid hastada mekanik ince barsak tıkanıklığına pnömobili ve distal ileumda tıkayıcı intraluminal taş eşlik etmektedir. Öncelik sıvı-elektrolit resüsitasyonu, nazogastrik dekompresyon ve obstrüksiyonu giderecek enterotomi-enterolitotomi işlemidir. Aynı seansta kolesistektomi ve fistül kapatma uzun operasyon ve morbidite riskini artırabileceği için çoğu yüksek riskli hastada seçici/ertelenmiş düşünülür.",
    "pearls": [
      "Pnömobili + ektopik taş + mekanik obstrüksiyon safra taşı ilişkili ileus paternidir.",
      "Yaşlı ve komorbid hastada temel hedef tıkanıklığı gidermektir.",
      "Fistül ve safra kesesi cerrahisi her hastada aynı seansta zorunlu değildir."
    ],
    "optionFeedback": {
      "Kolonoskopik dekompresyon yapıp rektal tüp yerleştirmek": "Kolonoskopik dekompresyon sigmoid volvulus gibi distal kalın barsak tıkanıklıklarında seçilmiş hastada işe yarayabilir. Bu vakada geçiş noktası distal ileumdadır ve tıkayıcı odak intraluminal büyük bir taştır. Kolonoskopi ince barsaktaki taşı güvenilir şekilde ortadan kaldırmaz ve yaşlı hastada gecikme sıvı kaybı ile aspirasyon riskini artırır. Dolayısıyla mekanik tıkanıklık kaynağına yönelik cerrahi gereklidir.",
      "Yalnızca nazogastrik dekompresyonla 72 saat konservatif izlemek": "Nazogastrik dekompresyon ve sıvı-elektrolit replasmanı başlangıç resüsitasyonunun önemli parçalarıdır; ancak bu tabloda tek başına uzun konservatif izlem yeterli değildir. BT'de net geçiş noktası, ektopik tıkayıcı taş ve pnömobili vardır. Taş lümeni mekanik olarak kapattığı için obstrüksiyonun kendiliğinden çözülmesi beklenmez. Konservatif bekleme yaşlı hastada aspirasyon, böbrek fonksiyon bozulması ve perforasyon riskini artırabilir.",
      "Laparoskopik kolesistektomi ve koledok eksplorasyonunu tek başına yapmak": "Kolesistektomi ve koledok eksplorasyonu tek başına distal ileumdaki tıkayıcı taşı ortadan kaldırmaz. Ayrıca yaşlı ve komorbid hastada fistül alanına geniş hepatobiliyer girişim eklemek operasyon süresini ve komplikasyon riskini artırabilir. Safra kesesi ve fistül cerrahisi seçilmiş düşük riskli hastada ya da tekrarlayan biliyer sorunlarda değerlendirilebilir; bu hastada ilk hedef barsak tıkanıklığının giderilmesidir.",
      "Sıvı-elektrolit resüsitasyonu sonrası enterotomi ile tıkayıcı taşı çıkarmak, fistül cerrahisini seçilmiş hastaya ertelemek": "Bu seçenek bu hasta için doğru önceliği verir. Hasta mekanik ince barsak tıkanıklığı, kusmaya bağlı sıvı-elektrolit kaybı ve BT'de distal ileumda tıkayıcı taş ile başvurmuştur. Önce resüsitasyon ve nazogastrik dekompresyon yapılır, ardından enterotomi ile taş çıkarılarak obstrüksiyon giderilir. Yaşlı ve kardiyak komorbiditesi olan hastada kolesistektomi-fistül kapatma aynı seansta zorunlu değildir; morbiditeye göre ertelenebilir veya hiç yapılmayabilir.",
      "Acil ERCP ile distal koledoktan taşı çıkarmak": "ERCP koledok taşları, kolanjit veya safra yolu obstrüksiyonunda terapötik rol oynar. Burada taş distal koledokta değil, ince barsak lümeni içinde mekanik tıkanıklık yapmaktadır. ERCP pnömobili ve fistül varlığını açıklayan biliyer-enterik iletiyi değerlendirebilir; fakat distal ileumdaki taşı çıkaramaz. Bu nedenle tedavi hedefi barsak lümenindeki tıkayıcı odağın cerrahi olarak ortadan kaldırılmasıdır."
    }
  },
  "coreKnowledge": "Safra taşı ilişkili ileusta BT'de mekanik ince barsak obstrüksiyonu, pnömobili ve ektopik taş birlikteliği beklenir; yüksek riskli yaşlı hastada çoğunlukla enterolitotomi ile obstrüksiyonun giderilmesi önceliklidir.",
  "examPearl": "Pnömobili + distal ileumda taş + yaşlı hastada SBO = önce enterolitotomi; kolesistektomi-fistül kapatma her hastada aynı seansta şart değildir.",
  "whyCorrect": "BT tıkayıcı taşın distal ileumda olduğunu göstermektedir. Yaşlı ve hipovolemik hastada doğru sıra resüsitasyon, dekompresyon ve obstrüksiyonu giderecek enterolitotomidir.",
  "optionComparison": "Doğru seçenek mekanik tıkanıklığın kaynağına yönelir. Yanlış seçenekler ya farklı hastalıkların tedavisidir ya da tıkanıklığı çözmeden beklemeyi önerir.",
  "evidenceChain": [
    "Aralıklı kusma, distansiyon ve gaz-gaita çıkaramama → mekanik obstrüksiyon kliniğidir.",
    "BT'de distal ileumda intraluminal hiperdens odak → tıkayıcı taş düzeyini gösterir.",
    "Pnömobili ve safra kesesi-duodenum komşuluğunda hava → biliyer-enterik fistül zeminiyle uyumludur.",
    "Hipokalemi, alkaloz ve kreatinin artışı → cerrahi öncesi sıvı-elektrolit resüsitasyonu gerekir."
  ],
  "whyWrong": "Yanlış seçenekler kolon volvulusu, koledok taşı veya safra kesesi cerrahisi gibi farklı hedeflere yönelir ya da mekanik tıkanıklığı gereksiz geciktirir.",
  "investigationLayerMeta": {
    "objective": "Safra taşı ilişkili mekanik obstrüksiyonda enterolitotomi ve yüksek riskli hastada sınırlı cerrahi kararını öğretme",
    "note": "V320 yeni Genel Cerrahi kaydı; mevcut SBO/kolanjit/kolesistit kayıtlarından farklı olarak pnömobili-ektopik taş karar noktasını hedefler."
  },
