  "question": "Bu hastada en uygun yönetim yaklaşımı aşağıdakilerden hangisidir?",
  "questionType": "postoperative_complication_management",
  "answerTarget": "Sleeve gastrektomi sonrası stabil hastada kaçak yönetimi ve kaynak kontrolü",
  "diagnosis": {
    "correct": "Geniş spektrum antibiyotik, sıvı resüsitasyonu, koleksiyon drenajı ve uygun endoskopik kapatma/drenaj stratejisiyle multidisipliner kaynak kontrolü sağlamak",
    "options": [
      "Oral alımı artırıp taburculuk planını sürdürmek",
      "Geniş spektrum antibiyotik, sıvı resüsitasyonu, koleksiyon drenajı ve uygun endoskopik kapatma/drenaj stratejisiyle multidisipliner kaynak kontrolü sağlamak",
      "Sadece proton pompa inhibitörü verip kaçak hattının spontan kapanmasını beklemek",
      "Stabil hastada herhangi bir drenaj yapmadan yüksek doz steroid başlamak",
      "Hastayı elektif koşullarda bir ay sonra kontrol BT için çağırmak"
    ],
    "question": "Bu hastada en uygun yönetim yaklaşımı aşağıdakilerden hangisidir?",
    "explanation": "Sleeve gastrektomi sonrası 5. günde ateş, belirgin taşikardi, sol omuz/üst karın ağrısı, yüksek inflamatuvar belirteçler ve BT'de staple hattı komşuluğunda oral kontrast içeren hava-sıvı koleksiyonu postoperatif kaçak ve septik odak anlamına gelir. Stabil hastada tedavi tek bir ilaçla beklemek değil; sıvı resüsitasyonu, geniş spektrum antibiyotik, oral alımın kesilmesi, koleksiyon drenajı, beslenme desteği ve uygun endoskopik stent/internal drenaj veya cerrahi girişim seçeneklerinin birlikte planlanmasıdır.",
    "pearls": [
      "Bariatrik cerrahi sonrası açıklanamayan taşikardi kaçak için çok önemli erken uyarıdır.",
      "Stabil hastada kaynak kontrol genellikle antibiyotik + drenaj + endoskopik/cerrahi stratejinin birlikte planlanmasıdır.",
      "Kaçak yönetiminde sadece beklemek septik komplikasyonları artırır."
    ],
    "optionFeedback": {
      "Oral alımı artırıp taburculuk planını sürdürmek": "Bu hastada oral alımı artırmak ve taburculuk planlamak tehlikelidir. Taşikardi, ateş, yüksek CRP/prokalsitonin ve BT'de oral kontrastın koleksiyona geçmesi postoperatif kaçak odağını gösterir. Oral alım devam ettikçe kaçak hattından kontaminasyon sürebilir. Taburculuk yerine yakın monitörizasyon, resüsitasyon ve kaynak kontrol gerekir.",
      "Geniş spektrum antibiyotik, sıvı resüsitasyonu, koleksiyon drenajı ve uygun endoskopik kapatma/drenaj stratejisiyle multidisipliner kaynak kontrolü sağlamak": "Bu seçenek doğru multidisipliner yönetim mantığını verir. Hasta hemodinamik olarak tamamen çökmemiş olsa da taşikardisi, ateşi, laktat yüksekliği ve BT'de staple hattı komşuluğunda kontrastlı koleksiyonu vardır. Tedavide sıvı resüsitasyonu, geniş spektrum antibiyotik, oral alımın kesilmesi, koleksiyonun perkütan veya cerrahi drenajı ve uygun endoskopik stent/internal drenaj gibi kaçak kontrol seçenekleri birlikte değerlendirilir. Amaç sepsisi kontrol etmek, kontaminasyonu azaltmak ve hastayı beslenme açısından desteklemektir.",
      "Sadece proton pompa inhibitörü verip kaçak hattının spontan kapanmasını beklemek": "Proton pompa inhibitörü üst gastrointestinal cerrahi sonrası asit baskılama için destekleyici olabilir; fakat tek başına kaçak ve koleksiyon tedavisi değildir. BT'de ekstraluminal oral kontrast geçişi ve hava-sıvı koleksiyonu vardır. Bu odağın drenajsız ve antibiyotiksiz bırakılması sepsis, apse büyümesi ve kronik fistül riskini artırır. PPI ancak ana kaynak kontrol tedavisinin yanında yer alabilir.",
      "Stabil hastada herhangi bir drenaj yapmadan yüksek doz steroid başlamak": "Steroid, postoperatif enfeksiyon ve kaçak ortamında iyileşmeyi bozabilir ve immün yanıtı baskılayabilir. Stabil hastada dahi koleksiyon drenajı ve kaçak hattının kontrolü gerekir. Herhangi bir drenaj yapmadan steroid başlamak hem sepsis odağını bırakır hem de doku onarımını olumsuz etkileyebilir. Bu nedenle bu yaklaşım vaka verileriyle bağdaşmaz.",
      "Hastayı elektif koşullarda bir ay sonra kontrol BT için çağırmak": "Bir ay sonraya kontrol planlamak, mevcut septik odağı tedavisiz bırakmak anlamına gelir. Hastada ateş, taşikardi, inflamatuvar belirteç yüksekliği ve BT ile gösterilmiş ekstraluminal kontrast geçişi vardır. Bu bulgular aktif komplikasyon yönetimi gerektirir. Kontrol BT takipte kullanılabilir; fakat ilk yaklaşım kaynak kontrol ve resüsitasyondur."
    }
  },
  "coreKnowledge": "Sleeve gastrektomi sonrası kaçakta açıklanamayan taşikardi erken alarmdır; BT ile koleksiyon/kontrast kaçağı gösterilen hastada antibiyotik, drenaj, endoskopik veya cerrahi kaynak kontrol ve beslenme desteği birlikte planlanır.",
  "examPearl": "Bariatrik cerrahi sonrası taşikardi + ateş + sol omuz ağrısı = kaçak düşün; stabilse dahi antibiyotik ve drenaj/endoskopik kaynak kontrol gerekir.",
  "whyCorrect": "Vaka BT ile desteklenen kapalı koleksiyonlu staple hattı kaçağını gösterir. Stabil hastada multimodal kaynak kontrol ve resüsitasyon en doğru yönetimdir.",
  "optionComparison": "Doğru seçenek aktif kaynak kontrol ve sepsis yönetimini birlikte ele alır. Yanlış seçenekler oral alım, tek ilaç, steroid veya gecikmiş takip gibi septik odağı tedavisiz bırakan yaklaşımlardır.",
  "evidenceChain": [
    "Postoperatif 5. gün taşikardi ve ateş → bariatrik cerrahi sonrası kaçak için alarm bulgudur.",
    "Sol omuza yayılan üst karın ağrısı → subfrenik/perigastrik irritasyonla uyumludur.",
    "BT'de oral kontrastlı hava-sıvı koleksiyonu → staple hattı çevresinde ekstraluminal kaynak gösterir.",
    "Lökosit, CRP, prokalsitonin ve laktat yüksekliği → septik yanıt ve erken hipoperfüzyon riskini destekler."
  ],
  "whyWrong": "Yanlış seçenekler kaynak kontrolü geciktirir veya enfeksiyon/kaçak patofizyolojisini hedeflemez.",
  "investigationLayerMeta": {
    "objective": "Sleeve gastrektomi sonrası kaçakta taşikardi alarmı ve multimodal kaynak kontrolünü öğretme",
    "note": "V320 yeni Genel Cerrahi kaydı; önceki enterokutan fistül/anastomoz kaçağı kayıtlarından farklı olarak bariatrik staple hattı kaçağını hedefler."
  },
