  "question": "Bu hastada cerrahiye giden en uygun yaklaşım aşağıdakilerden hangisidir?",
  "questionType": "surgicalDecision",
  "answerTarget": "İnsülinomada biyokimyasal doğrulama, lokalizasyon ve parankim koruyucu cerrahi",
  "diagnosis": {
    "correct": "Biyokimyasal tanı ve lokalizasyon sonrası küçük, yüzeyel ve ana pankreatik kanaldan uzak lezyonda enükleasyon; uygun olmayan lokalizasyonda sınırlı rezeksiyon planlamak",
    "options": [
      "Önce total pankreatektomi yapıp ömür boyu insülin ve enzim replasmanı başlamak",
      "Sadece sık aralıklı karbonhidrat önerip pankreas lezyonunu izlemek",
      "Biyokimyasal tanı ve lokalizasyon sonrası küçük, yüzeyel ve ana pankreatik kanaldan uzak lezyonda enükleasyon; uygun olmayan lokalizasyonda sınırlı rezeksiyon planlamak",
      "Somatostatin analoğu verip cerrahi değerlendirmeyi tamamen bırakmak",
      "ERCP ile pankreas kanalına stent koyup hipoglisemi ataklarını tedavi etmek"
    ],
    "question": "Bu hastada cerrahiye giden en uygun yaklaşım aşağıdakilerden hangisidir?",
    "explanation": "Açlıkla gelen nöroglikopenik belirtilerin düşük plazma glukozu sırasında görülmesi ve glukozla düzelmesi Whipple triadını oluşturur. Aynı anda insülin ve C-peptidin baskılanmaması, sülfonilüre taramasının negatif olması endojen hiperinsülinemiyi destekler. Lokalize küçük ve kanal uzak pankreatik lezyonda cerrahi hedef parankimi koruyarak enükleasyon yapmaktır; kanal yakınlığı, kuyruk yerleşimi veya çoklu lezyon durumunda sınırlı rezeksiyon planı değişebilir.",
    "pearls": [
      "İnsülinomada tanı için hipoglisemi anında insülin/C-peptid baskılanmaması beklenir.",
      "Sülfonilüre negatifliği endojen tümöral insülin salınımını destekler.",
      "Küçük, yüzeyel ve ana kanaldan uzak lezyonda enükleasyon parankim koruyucu seçenektir."
    ],
    "optionFeedback": {
      "Önce total pankreatektomi yapıp ömür boyu insülin ve enzim replasmanı başlamak": "Total pankreatektomi bu vaka için aşırı morbid bir yaklaşımdır. Hastada küçük, lokalize, metastazsız ve ana kanaldan uzak görünen tek lezyon vardır. Tüm pankreası çıkarmak hastayı brittle diyabet ve ekzokrin pankreas yetmezliğiyle karşı karşıya bırakır. Total pankreatektomi ancak yaygın, kontrol edilemeyen veya seçilmiş çok özel durumlarda gündeme gelir; bu vakada hedef parankim koruyucu cerrahidir.",
      "Sadece sık aralıklı karbonhidrat önerip pankreas lezyonunu izlemek": "Sık öğün ve karbonhidrat alımı ameliyata kadar semptomları azaltmak için geçici destek sağlayabilir; fakat biyokimyasal olarak kanıtlanmış endojen hiperinsülinemiyi ve lokalize pankreas lezyonunu tedavi etmez. Ataklar nöroglikopenik düzeye ulaşmış ve hasta bilinç değişikliği yaşamıştır. Sadece diyet önerisiyle izlem, travma, nöbet veya kalıcı nörolojik etkilenme riskini sürdürür. Cerrahi değerlendirme gerekir.",
      "Biyokimyasal tanı ve lokalizasyon sonrası küçük, yüzeyel ve ana pankreatik kanaldan uzak lezyonda enükleasyon; uygun olmayan lokalizasyonda sınırlı rezeksiyon planlamak": "Bu seçenek doğru cerrahi mantığı verir. Hastada Whipple triadı, hipoglisemi sırasında uygunsuz yüksek insülin ve C-peptid, negatif sülfonilüre taraması ve lokalize küçük hipervasküler pankreatik lezyon vardır. Lezyon küçük, yüzeyel ve ana pankreatik kanaldan yeterince uzaksa enükleasyon parankim koruyucu ve etkili bir yaklaşımdır. Kanal yakınlığı, derin yerleşim veya kuyrukta rezeksiyon gerektiren anatomik koşullarda distal pankreatektomi gibi sınırlı rezeksiyon planlanabilir.",
      "Somatostatin analoğu verip cerrahi değerlendirmeyi tamamen bırakmak": "Somatostatin analoğu bazı nöroendokrin tümörlerde semptom kontrolü için kullanılabilir; ancak insülinomada yanıt değişkendir ve cerrahiye uygun lokalize hastalıkta küratif yaklaşımın yerine geçmez. Bu hastanın lezyonu küçük ve lokalizedir. Cerrahiyi tamamen bırakmak, tekrarlayan ciddi hipoglisemi ataklarını ve nöroglikopenik riski devam ettirir. Medikal tedavi ancak cerrahiye kadar köprü veya cerrahiye uygun olmayan hastada düşünülür.",
      "ERCP ile pankreas kanalına stent koyup hipoglisemi ataklarını tedavi etmek": "ERCP pankreatik kanal taşları, safra yolu problemleri veya bazı darlıkların yönetiminde kullanılabilir; endojen hiperinsülinemiyi tedavi etmez. Bu hastada ana problem hormon salgılayan küçük pankreatik nöroendokrin lezyondur. Pankreas kanalına stent koymak insülin salınımını azaltmaz ve gereksiz pankreatit riski doğurabilir. Cerrahi plan lokalizasyon ve kanal ilişkisine göre yapılmalıdır."
    }
  },
  "coreKnowledge": "İnsülinomada tanı hipoglisemi anında uygunsuz yüksek insülin/C-peptid ve dış kaynaklı ilaç alımının dışlanmasıyla konur; lokalize, küçük ve kanal uzak lezyonda enükleasyon parankim koruyucu cerrahidir.",
  "examPearl": "Whipple triadı + hipoglisemide yüksek C-peptid = endojen hiperinsülinemi; küçük kanal uzak insülinomada enükleasyon düşün.",
  "whyCorrect": "Vaka endojen hiperinsülinemi ve lokalize küçük pankreatik NET paternindedir. Cerrahi yaklaşım lezyon anatomisine göre parankim koruyucu olmalıdır.",
  "optionComparison": "Doğru seçenek biyokimyasal tanı ile anatomik lokalizasyonu birleştirir. Yanlış seçenekler ya aşırı geniş cerrahi yapar, ya yalnız destek tedavisi verir, ya da pankreas kanalını gereksiz hedefler.",
  "evidenceChain": [
    "Açlıkla semptom ve glukozla düzelme → Whipple triadını tamamlar.",
    "Glukoz 42 mg/dL iken insülin ve C-peptidin yüksek olması → endojen hiperinsülinemi lehinedir.",
    "Sülfonilüre taramasının negatifliği → ilaçla tetiklenen hipoglisemi olasılığını azaltır.",
    "Küçük, hipervasküler ve kanal uzak pankreas lezyonu → parankim koruyucu cerrahi için anatomik hedef sunar."
  ],
  "whyWrong": "Yanlış seçenekler lokalize fonksiyonel pankreatik tümörün küratif cerrahi potansiyelini ya abartılı rezeksiyonla ya da yetersiz medikal/endoskopik yaklaşımla yönetir.",
  "investigationLayerMeta": {
    "objective": "İnsülinomada Whipple triadı, endojen hiperinsülinemi ve enükleasyon kararını öğretme",
    "note": "V320 yeni Genel Cerrahi kaydı; önceki pankreatit/nekroz kayıtlarından farklı olarak fonksiyonel pankreatik nöroendokrin tümör cerrahisini hedefler."
  },
