  "clinicalFocus": "Postoperatif dönemde mekanik tıkanıklık olmadan gelişen belirgin kolon dilatasyonunda konservatif tedavi sonrası farmakolojik dekompresyon kararını ayırt etme.",
  "learningTarget": "Akut kolonik psödo-obstrüksiyonda mekanik obstrüksiyon, volvulus, iskemi ve perforasyon ayrımını yaparak doğru yönetim basamağını seçme.",
  "demographics": "76 yaşında erkek hasta",
