    "historySummary": "Hasta üç gün önce kalça protezi ameliyatı geçirmiştir ve ameliyattan beri yatakta daha az hareket ettiğini anlatır. Son iki gündür karnının giderek şiştiğini, gaz çıkaramadığını ve bulantısının arttığını söyler. Ağrı sürekli keskin tarzda değildir; daha çok yaygın gerginlik ve baskı hissi şeklindedir. Opioid analjezik kullandığını, ameliyat öncesi bağırsak alışkanlığında belirgin değişiklik olmadığını belirtir. Son saatlerde kusma olmamış, dışkıda kan fark etmemiş ve daha önce kolon kanseri nedeniyle ameliyat geçirmemiştir."
