  "question": "Bu hastada acil yönetimde en uygun yaklaşım aşağıdakilerden hangisidir?",
  "questionType": "acuteManagement",
  "answerTarget": "Peritonit olmayan mezenterik ven trombozunda antikoagülasyon ve cerrahi eşiklerini doğru kurma",
  "diagnosis": {
    "correct": "İntravenöz unfractionated heparin ile terapötik antikoagülasyon başlamak, sıvı desteği ve seri karın muayenesiyle iskemi bulgularını izlemek",
    "options": [
      "Acil superior mezenterik arter embolektomisi yapmak",
      "Acil eksploratif laparotomiyle tüm ödemli ince barsak anslarını rezeke etmek",
      "Sadece geniş spektrumlu antibiyotik ve analjeziyle antikoagülasyonsuz izlemek",
      "İntravenöz unfractionated heparin ile terapötik antikoagülasyon başlamak, sıvı desteği ve seri karın muayenesiyle iskemi bulgularını izlemek",
      "Kolonoskopik dekompresyon ve rektal tüp yerleştirmek"
    ],
    "question": "Bu hastada acil yönetimde en uygun yaklaşım aşağıdakilerden hangisidir?",
    "explanation": "Hasta tromboz risk faktörleriyle başvurmuş, BT’de mezenterik venöz sistemde trombüs ve venöz konjesyon gösterilmiştir. Arteriyel akım korunmakta, peritonit ve perforasyon bulguları bulunmamaktadır. Bu nedenle ilk basamak terapötik antikoagülasyon, sıvı desteği, bağırsak istirahati ve seri muayenedir. Klinik kötüleşme, peritonit, yükselen laktat veya barsak nekrozu bulguları gelişirse cerrahi eksplorasyon gerekir.",
    "pearls": [
      "Mezenterik ven trombozunda ilk tedavi çoğu stabil hastada antikoagülasyondur.",
      "Peritonit ve transmural nekroz cerrahi eşiği belirler.",
      "Arteriyel SMA tıkanıklığı ile venöz tromboz tedavisi aynı değildir."
    ],
    "optionFeedback": {
      "Acil superior mezenterik arter embolektomisi yapmak": "Superior mezenterik arter embolektomisi arteriyel embolik tıkanıklıkta, özellikle atriyal fibrilasyonlu hastada ani başlayan şiddetli ağrı ve arteriyel dolum defekti varsa düşünülür. Bu vakada BT venöz fazda superior mezenterik ven ve dallarında trombüs göstermektedir; SMA akımı korunmuştur. Arteriyel embolektomi venöz çıkış tıkanıklığını çözmez ve gereksiz invaziv işlem olur. Arteriyel ve venöz mezenter iskemi ayrımı TUS düzeyinde kritik bir ayırıcı noktadır.",
      "Acil eksploratif laparotomiyle tüm ödemli ince barsak anslarını rezeke etmek": "Laparotomi; peritonit, transmural nekroz, perforasyon, pnömatozisle birlikte klinik kötüleşme veya kontrol edilemeyen sepsis varsa gerekir. Bu hastada barsak duvarı ödemli ve ağrı belirgin olsa da rebound-defans yoktur, laktat ağır yükselmemiştir ve BT’de serbest hava ya da yaygın pnömatozis saptanmamıştır. Tüm ödemli ansları rezeke etmek kısa bağırsak sendromu riskini artırır. Venöz mezenter iskemide canlılığı belirsiz barsağı gereksiz çıkarmamak ve antikoagülasyonla venöz akımı düzeltmeye çalışmak temel yaklaşımdır.",
      "Sadece geniş spektrumlu antibiyotik ve analjeziyle antikoagülasyonsuz izlemek": "Antibiyotik ve analjezi destek sağlayabilir; ancak mezenterik ven trombozunun ana tedavisi trombüs progresyonunu durduracak terapötik antikoagülasyondur. Antikoagülasyon verilmezse venöz tıkanıklık ilerleyebilir, barsak ödemi artabilir ve transmural iskemi gelişebilir. Antibiyotik tek başına ancak enfeksiyon veya nekroz riski eşlik ediyorsa yardımcıdır; pıhtıyı tedavi etmez. Bu nedenle antikoagülasyonsuz izlem eksik ve risklidir.",
      "İntravenöz unfractionated heparin ile terapötik antikoagülasyon başlamak, sıvı desteği ve seri karın muayenesiyle iskemi bulgularını izlemek": "Bu seçenek doğru yaklaşımdır. Hastada kontrastlı BT venöz fazda superior mezenterik ven trombozu, barsak duvar ödemi ve mezenterik konjesyon göstermektedir; buna karşın peritonit, serbest hava, belirgin pnömatozis veya şok yoktur. Bu tablo cerrahi rezeksiyondan önce terapötik antikoagülasyon, sıvı desteği, bağırsak istirahati, ağrı kontrolü ve çok yakın klinik izlem gerektirir. Unfractionated heparin kısa etkili ve geri döndürülebilir olduğu için olası cerrahi gereksinimi olan akut hastada pratiktir. Peritonit veya nekroz gelişirse cerrahi eksplorasyon geciktirilmez.",
      "Kolonoskopik dekompresyon ve rektal tüp yerleştirmek": "Kolonoskopik dekompresyon sigmoid volvulus veya akut kolonik psödo-obstrüksiyon gibi kolon distansiyonu odaklı durumlarda kullanılır. Bu vakada sorun kolon lümeninde gaz basıncı değil, mezenterik venöz dönüşün trombüsle bozulmasıdır. BT’de ince barsak duvar ödemi ve venöz dolum defekti vardır. Rektal tüp venöz trombüsü çözmez ve mezenterik iskemi takibini geciktirebilir."
    }
  },
  "coreKnowledge": "Mezenterik ven trombozunda peritonit yoksa terapötik antikoagülasyon ana tedavidir; cerrahi, nekroz veya perforasyon bulgusu gelişen hastada gecikmeden uygulanır.",
  "examPearl": "SMV dolum defekti + peritonit yok + SMA açık = heparin ve seri muayene; tahta karın/laktat yükselişi olursa ameliyat.",
  "whyCorrect": "BT venöz trombozu göstermekte ve hastada henüz transmural nekroz bulgusu bulunmamaktadır. Bu nedenle hedef pıhtı ilerlemesini durdurmak ve bağırsak canlılığını yakın izlemle değerlendirmektir.",
  "optionComparison": "Doğru seçenek venöz etiyolojiyi hedefler ve cerrahi eşiğini saklı tutar. Yanlış seçenekler arteriyel tıkanıklık, lümen basıncı veya nekroz varmış gibi davranır.",
  "evidenceChain": [
    "Oral kontraseptif ve uzun yolculuk öyküsü → venöz tromboz riskini artırır.",
    "BT’de SMV dolum defekti → primer problem venöz dönüş tıkanıklığıdır.",
    "SMA akımının açık olması → arteriyel embolektomi gerektiren paterni zayıflatır.",
    "Peritonit ve serbest hava olmaması → ilk aşamada tüm barsağı rezeke etmek yerine antikoagülasyon ve yakın izleme izin verir."
  ],
  "whyWrong": "Yanlış seçenekler pıhtının venöz doğasını gözden kaçırır veya henüz nekroz kanıtı olmayan barsağa aşırı cerrahi yaklaşır.",
  "investigationLayerMeta": {
    "objective": "Mezenterik ven trombozunda konservatif-antikoagülan tedavi ile cerrahi eşik ayrımını öğretme",
    "note": "V321 yeni Genel Cerrahi kaydı; mevcut arteriyel mezenter iskemi kayıtlarından farklı olarak venöz tromboz yönetimini hedefler."
  },
