  "question": "Bu hasta için en uygun acil yönetim planı aşağıdakilerden hangisidir?",
  "questionType": "acuteManagement",
  "answerTarget": "Paraözofageal herni ilişkili akut gastrik volvulusta dekompresyon ve definitif onarım sırasını seçme",
  "diagnosis": {
    "correct": "Acil endoskopik dekompresyon ve nazogastrik tüp yerleştirmeyi denemek; stabilizasyon sonrası aynı yatışta paraözofageal herni onarımı ve gastropeksi/fundoplikasyon planlamak",
    "options": [
      "Acil endoskopik dekompresyon ve nazogastrik tüp yerleştirmeyi denemek; stabilizasyon sonrası aynı yatışta paraözofageal herni onarımı ve gastropeksi/fundoplikasyon planlamak",
      "Proton pompa inhibitörü ve antiemetikle taburcu edip elektif poliklinik kontrolü vermek",
      "Kolonoskopik detorsiyon yapıp rektal tüp yerleştirmek",
      "Acil kolesistektomi ve koledok eksplorasyonu yapmak",
      "Sadece geniş spektrumlu antibiyotik başlayıp ağızdan beslenmeyi sürdürmek"
    ],
    "question": "Bu hasta için en uygun acil yönetim planı aşağıdakilerden hangisidir?",
    "explanation": "Klinik olarak şiddetli epigastrik ağrı, öğürme ve nazogastrik tüpün ilerletilememesi; BT’de intratorasik mide ve organoaksiyel rotasyonla birleştiğinde akut gastrik volvulus paternidir. Perforasyon veya nekroz bulgusu yoksa endoskopik dekompresyon hastayı stabilize edebilir. Ancak büyük paraözofageal herni devam ettiği için rekürrens ve strangülasyon riski vardır; bu nedenle aynı yatışta cerrahi herni onarımı ve mide fiksasyonu planlanmalıdır.",
    "pearls": [
      "Öğürme + NG tüpün ilerletilememesi üst GIS kapalı loop riskini gösterir.",
      "BT’de intratorasik mide ve organoaksiyel rotasyon tanısal kararı güçlendirir.",
      "İskemi/perforasyon yoksa dekompresyonla stabilizasyon, ardından definitif onarım mantıklıdır."
    ],
    "optionFeedback": {
      "Acil endoskopik dekompresyon ve nazogastrik tüp yerleştirmeyi denemek; stabilizasyon sonrası aynı yatışta paraözofageal herni onarımı ve gastropeksi/fundoplikasyon planlamak": "Bu seçenek doğru yaklaşımı özetler. Hastada epigastrik-göğüs ağrısı, öğürme, nazogastrik tüp ilerletilememesi ve BT’de intratorasik mide ile organoaksiyel rotasyon vardır. Perforasyon veya belirgin nekroz yoksa ilk hedef mideyi dekomprese ederek kapalı loop basısını azaltmak ve aspirasyon/iskemi riskini düşürmektir. Endoskopik dekompresyon hastayı stabilize edebilir; ancak altta yatan büyük paraözofageal herni düzeltilmezse rekürrens ve strangülasyon riski sürer. Bu nedenle aynı yatışta cerrahi onarım planı doğru cevabın önemli parçasıdır.",
      "Proton pompa inhibitörü ve antiemetikle taburcu edip elektif poliklinik kontrolü vermek": "PPI ve antiemetik reflü veya basit gastrit yakınmalarında semptomatik fayda sağlayabilir; fakat akut gastrik rotasyon ve tıkanma paternini çözmez. Bu hastanın ağrısı, öğürmesi, distansiyonu ve NG tüpün ilerletilememesi mekanik kapalı loop riskini gösterir. Taburculuk mide iskemisi, perforasyon ve aspirasyon riskini artırır. Semptomlar geçici azalsa bile akut paraözofageal herni ilişkili volvulus aktif dekompresyon ve definitif cerrahi plan gerektirir.",
      "Kolonoskopik detorsiyon yapıp rektal tüp yerleştirmek": "Kolonoskopik detorsiyon sigmoid volvulus için uygundur; işlem hedefi kolon lümenindeki torsiyonu açmaktır. Bu vakada sorun kolon değil midenin toraks içine herniye olup kendi ekseni etrafında dönmesidir. Rektal tüp mide distansiyonunu azaltmaz ve intratorasik mideyi düzeltmez. Görüntüleme ve NG tüpün ilerlememesi üst GIS kaynaklı kapalı loop paternini destekler.",
      "Acil kolesistektomi ve koledok eksplorasyonu yapmak": "Kolesistektomi ve koledok eksplorasyonu safra kesesi veya safra yolu patolojilerinde uygulanır. Bu hastada sarılık, kolestatik laboratuvar paterni veya safra yolu dilatasyonu yoktur. BT’de temel bulgu intratorasik mide ve organoaksiyel rotasyondur. Safra cerrahisi hem problemi çözmez hem de akut mide strangülasyonu riskini geciktirir.",
      "Sadece geniş spektrumlu antibiyotik başlayıp ağızdan beslenmeyi sürdürmek": "Antibiyotik, perforasyon, mediastinit, aspirasyon pnömonisi veya iskemik/nekrotik mide şüphesi varsa destek olarak eklenebilir; ancak tek başına mekanik obstrüksiyonu tedavi etmez. Ağızdan beslenmeyi sürdürmek distansiyonu artırabilir ve aspirasyon riskini yükseltir. Bu vakada öncelik ağızdan alımı kesmek, sıvı-resüsitasyon sağlamak ve mideyi dekomprese etmektir."
    }
  },
  "coreKnowledge": "Akut gastrik volvulusta amaç önce kapalı loop basısını azaltmak, iskemi/perforasyon bulgusu varsa acil cerrahi yapmak ve altta yatan paraözofageal herniyi definitif olarak onarmaktır.",
  "examPearl": "Öğürme + epigastrik ağrı + NG tüp geçmiyor + intratorasik mide = gastrik volvulus; stabil hastada dekompresyon sonrası aynı yatışta onarım.",
  "whyCorrect": "Vaka üst GIS kapalı loop paternindedir. Stabilite ve duvar kontrastlanmasının korunması, endoskopik dekompresyonla hazırlık olanağı verir; herni onarımı geciktirilirse nüks riski sürer.",
  "optionComparison": "Doğru seçenek hem acil basınç azaltmayı hem definitif anatomik düzeltmeyi içerir. Yanlış seçenekler reflü, safra yolu veya kolon volvulusu gibi farklı hastalıkların yönetimine kayar.",
  "evidenceChain": [
    "Yemek sonrası ani epigastrik-göğüs ağrısı ve öğürme → üst GIS tıkanma paternidir.",
    "Nazogastrik tüpün ilerletilememesi → kapalı loop mide rotasyonunu destekler.",
    "BT’de intratorasik mide ve organoaksiyel rotasyon → paraözofageal herni zeminindeki mekanik sorunu gösterir.",
    "Duvar kontrastlanmasının korunması ve serbest hava olmaması → perforasyonsuz stabilizasyon şansı verir."
  ],
  "whyWrong": "Yanlış seçenekler mideyi dekomprese etmez, altta yatan herniyi düzeltmez veya anatomik olarak ilgisiz organ sistemlerine yönelir.",
