  "question": "Bu hasta için en uygun definitif cerrahi yaklaşım aşağıdakilerden hangisidir?",
  "questionType": "surgicalDecision",
  "answerTarget": "Tip I koledok kistinde tam ekstrahepatik safra yolu eksizyonu ve Roux-en-Y hepatikojejunostomi seçimi",
  "diagnosis": {
    "correct": "Ekstrahepatik kistik safra yolu segmentinin tam eksizyonu, kolesistektomi ve Roux-en-Y hepatikojejunostomi yapmak",
    "options": [
      "ERCP ile sfinkterotomi ve geçici plastik stent yerleştirip uzun süre izlemek",
      "Sadece laparoskopik kolesistektomi yapmak",
      "Ekstrahepatik kistik safra yolu segmentinin tam eksizyonu, kolesistektomi ve Roux-en-Y hepatikojejunostomi yapmak",
      "Yalnız tekrarlayan ataklarda antibiyotik verip cerrahiyi malignite gelişene kadar ertelemek",
      "Malignite kanıtı olmasa bile tüm hastalara pankreatikoduodenektomi yapmak"
    ],
    "question": "Bu hasta için en uygun definitif cerrahi yaklaşım aşağıdakilerden hangisidir?",
    "explanation": "MRCP’de ekstrahepatik safra yolunda fusiform kistik genişleme vardır ve malignite/taşla açıklanan basit obstrüksiyon yoktur. Yetişkin koledok kistlerinde tekrarlayan kolanjit, taş, pankreatit ve malign dönüşüm riski nedeniyle uygun hastada kistik ekstrahepatik safra kanalının tam eksizyonu gerekir. Safra kesesi de çıkarılır ve biliyer-enterik süreklilik Roux-en-Y hepatikojejunostomi ile sağlanır. Endoskopik stent veya antibiyotik geçici destek olabilir; definitif risk azaltımı sağlamaz.",
    "pearls": [
      "Tip I koledok kistinde ana problem ekstrahepatik safra yolunun kistik segmentidir.",
      "Tam eksizyon uzun dönem komplikasyon ve malignite riskini azaltmayı hedefler.",
      "Rekonstrüksiyonda Roux-en-Y hepatikojejunostomi standart seçeneklerden biridir."
    ],
    "optionFeedback": {
      "ERCP ile sfinkterotomi ve geçici plastik stent yerleştirip uzun süre izlemek": "ERCP, kolanjit atağında geçici drenaj, taş çıkarılması veya tanısal/terapötik köprü olarak seçilmiş durumlarda kullanılabilir. Ancak tip I koledok kistinde sorun sadece distal akım değil, malign dönüşüm ve tekrarlayan inflamasyon riski taşıyan anormal ekstrahepatik safra yolu segmentidir. Stent kisti ortadan kaldırmaz, uzun dönem kanser riskini azaltmaz ve tekrarlayan kolanjit/pankreatit riskini sürdürür. Definitif tedavi kistik segmentin çıkarılması ve biliyer-enterik rekonstrüksiyondur.",
      "Sadece laparoskopik kolesistektomi yapmak": "Kolesistektomi safra kesesi taşını veya safra kesesi kanseri riskini tek başına ele alabilir; fakat fusiform dilate ekstrahepatik safra kanalını tedavi etmez. Bu hastanın MRCP bulgusu safra kesesiyle sınırlı değildir. Kistik ana safra kanalı bırakılırsa kolanjit, taş, striktür ve malign dönüşüm riski devam eder. Bu nedenle kolesistektomi ancak kist eksizyonu ve rekonstrüksiyonun bir parçası olarak anlamlıdır.",
      "Ekstrahepatik kistik safra yolu segmentinin tam eksizyonu, kolesistektomi ve Roux-en-Y hepatikojejunostomi yapmak": "Bu seçenek doğru definitif cerrahi yaklaşımdır. Tip I koledok kistinde ekstrahepatik safra yolu fusiform dilatedir ve uzun dönem komplikasyon/malignite riski taşır. Tedavide amaç kistik ekstrahepatik safra kanalını ve safra kesesini çıkarmak, ardından safra akımını Roux-en-Y hepatikojejunostomi ile güvenli şekilde sağlamaktır. Proksimal ve distal sınırların doğru belirlenmesi, pankreatik kanal bileşkesi ve varsa taş/striktürlerin değerlendirilmesi cerrahi planın önemli parçalarıdır.",
      "Yalnız tekrarlayan ataklarda antibiyotik verip cerrahiyi malignite gelişene kadar ertelemek": "Tekrarlayan kolanjit ataklarında antibiyotik akut enfeksiyonu baskılayabilir; ancak anatomik kistik dilatasyonu ve kanser riskini ortadan kaldırmaz. Semptomların aralıklı olması güvenli izlem anlamına gelmez. Koledok kisti tanısı konduktan sonra uygun hastada cerrahi rezeksiyon planlanmalıdır. Malignite gelişene kadar beklemek, tedavi edilebilir evredeki anatomik problemi yüksek riskli onkolojik hastalığa dönüştürebilir.",
      "Malignite kanıtı olmasa bile tüm hastalara pankreatikoduodenektomi yapmak": "Pankreatikoduodenektomi ampulla, distal koledok veya pankreas başı malignitesi gibi seçilmiş durumlarda gerekir. Tip I koledok kistinde malignite veya distal invazyon kanıtı yoksa her hastaya Whipple yapmak gereksiz morbidite yaratır. Cerrahi hedef ekstrahepatik kistik kanalın eksizyonu ve biliyer rekonstrüksiyondur. Whipple ancak kanser, distal safra yolu tutulumu veya güvenli sınır gerektiren özel anatomik durumlarda tartışılır."
    }
  },
  "coreKnowledge": "Koledok kistinde cerrahi, kistik safra yolu mukozasını geride bırakmamaya ve güvenli biliyer-enterik drenaj sağlamaya odaklanır; tip I kistte tam ekstrahepatik eksizyon + kolesistektomi + Roux-en-Y hepatikojejunostomi temel yaklaşımdır.",
  "examPearl": "Fusiform ekstrahepatik safra yolu genişliği + tekrarlayan kolanjit = stent/kolesistektomi değil, kist eksizyonu ve hepatikojejunostomi.",
  "whyCorrect": "Vaka taşsız ve kitlesiz fusiform ekstrahepatik safra yolu genişlemesi göstermektedir. Bu anatomik risk kalıcıdır; bu nedenle geçici drenaj veya yalnız safra kesesi cerrahisi yeterli değildir.",
  "optionComparison": "Doğru seçenek anatomik lezyonu çıkarır ve safra akımını yeniden kurar. Yanlış seçenekler geçici drenaja, yetersiz safra kesesi cerrahisine veya gereksiz büyük rezeksiyona kayar.",
  "evidenceChain": [
    "Tekrarlayan sağ üst kadran ağrısı, ateş ve aralıklı sarılık → biliyer sistemde kronik/anatomik sorun düşündüren klinik örüntüdür.",
    "MRCP’de fusiform ekstrahepatik genişleme → tip I koledok kisti paternini gösterir.",
    "Taş ve pankreas başı kitlesinin olmaması → basit koledokolitiazis veya pankreas kanseri yaklaşımını zayıflatır.",
    "Yetişkin yaşta semptomatik kistik safra yolu segmenti → definitif eksizyon ve rekonstrüksiyon ihtiyacını destekler."
  ],
  "whyWrong": "Yanlış seçenekler kistik safra yolu mukozasını geride bırakır ya da malignite kanıtı olmadan aşırı radikal pankreatik cerrahi önerir.",
  "investigationLayerMeta": {
    "objective": "Tip I koledok kistinde definitif hepatobiliyer cerrahi yaklaşımı öğretme",
    "note": "V321 yeni Genel Cerrahi kaydı; mevcut kolanjit/koledokolitiazis kayıtlarından farklı olarak konjenital safra yolu kisti yönetimini hedefler."
  },
