    "question": "Bu hasta için en uygun sonraki yönetim aşağıdakilerden hangisidir?",
    "explanation": "Appendiks nöroendokrin tümörlerinde küçük, uç yerleşimli ve düşük riskli lezyonlarda appendektomi yeterli olabilir. Bu vakada tümör 2 cm üzerinde, appendiks bazına yakın ve mezoappendiks invazyonu göstermektedir. Bu özellikler bölgesel nodal risk ve çekum/ileokolik drenaj alanının değerlendirilmesi gereksinimini artırır. Uygun evreleme sonrası sağ hemikolektomi ve lenf nodu diseksiyonu bu nedenle en uygun yaklaşımdır.",
    "pearls": [
      "Appendiks nöroendokrin tümöründe çap, yerleşim, mezoappendiks invazyonu, grade ve sınır durumu yönetimi belirler.",
      "2 cm üzerindeki veya yüksek riskli özellik taşıyan lezyonlarda sağ hemikolektomi gündeme gelir.",
      "Karinoid sendrom olmaması lokal onkolojik cerrahi gereksinimini ortadan kaldırmaz."
    ],
    "optionFeedback": {
      "Ek tedavi yapmadan yalnız yıllık tam kan sayımı ve karın muayenesiyle izlemek": "Sadece izlem küçük, iyi sınırlı ve düşük riskli appendiks nöroendokrin tümörlerinde kabul edilebilir olabilir. Ancak bu vakada tümör 2 cm sınırını aşmış, appendiks bazına yakın yerleşmiş ve mezoappendiks invazyonu göstermiştir. Bu özellikler nodal tutulum riskini ve ek rezeksiyon ihtiyacını artırır. Yıllık muayene ve kan sayımı, bölgesel lenf nodlarının cerrahi değerlendirilmesini ve onkolojik rezeksiyon ihtiyacını karşılamaz.",
      "Kolonoskopi sonucu normal olduğu için sadece somatostatin analoğu başlamak": "Somatostatin analogları fonksiyonel, metastatik veya semptomatik nöroendokrin tümörlerde sistemik kontrol amacıyla kullanılabilir. Lokalize appendiks tümöründe cerrahi risk faktörleri varken tek başına medikal tedavi onkolojik rezeksiyonun yerine geçmez. Kolonoskopinin normal olması senkron kolon kanseri açısından rahatlatıcıdır; fakat appendiks bazına yakın ve 2 cm üzerindeki tümörün lenfatik riskini ortadan kaldırmaz. Bu nedenle tedavi kararı yalnız kolonoskopiye göre verilmez.",
      "Sadece appendiks güdüğüne yönelik lokal re-eksizyon yapmak ve mezenterik lenf nodlarını değerlendirmemek": "Appendiks güdüğünün lokal re-eksizyonu pozitif güdük sınırı gibi çok sınırlı anatomik sorunlarda tartışılabilir; fakat bölgesel lenf nodu drenajını değerlendirmez. Bu vakada tümör çapı ve mezoappendiks invazyonu, daha geniş lenfovasküler risk alanını gündeme getirir. Lokal eksizyon çekum ve ileokolik lenfatikleri kapsamaz. Bu nedenle onkolojik amaçlı yaklaşım sağ kolon ve bölgesel lenf nodlarını içerecek şekilde planlanmalıdır.",
      "Adjuvan kemoterapi verip cerrahi rezeksiyonu tümör markerları yükselene kadar ertelemek": "Appendiks nöroendokrin tümörlerinde lokalize hastalıkta temel tedavi cerrahidir; kemoterapi tipik ilk basamak değildir. Tümör markerlarının yükselmesini beklemek, cerrahiyle kontrol edilebilecek bir hastalığı ilerlemiş evreye bırakabilir. Adjuvan tedavi kararı histoloji, evre, grade ve metastaz durumuna göre özel olarak değerlendirilir. Bu hasta için öncelik uygun evreleme sonrası onkolojik cerrahi tamamlamadır.",
      "Uygun evreleme sonrası sağ hemikolektomi ve bölgesel lenf nodu diseksiyonu planlamak": "Bu seçenek risk faktörlerine dayalı doğru onkolojik cerrahi mantığı kurar. Appendektomi materyalinde 2.3 cm nöroendokrin tümör, bazal yerleşim ve mezoappendiks invazyonu bulunması, yalnız appendektominin yetersiz kalabileceğini gösterir. Sağ hemikolektomi ile ileokolik lenfatik drenaj alanı ve çekum komşuluğu değerlendirilir; bölgesel lenf nodu diseksiyonu evreleme ve tedavi değerine sahiptir. Operasyon öncesi kolonoskopi ve kesitsel görüntüleme senkron lezyon/metastaz açısından tamamlayıcıdır, ancak cerrahi kararın ana gerekçesi patolojik risk profilidir."
    }
