  "coreKnowledge": "Appendiks nöroendokrin tümörlerinde appendektomi yeterliliği tümör çapı ve risk faktörlerine bağlıdır; 2 cm üzeri, bazal yerleşim, mezoappendiks invazyonu veya sınır sorunu sağ hemikolektomi kararını güçlendirir.",
  "examPearl": "Appendektomi patolojisinde 2 cm üzeri appendiks NET + mezoappendiks invazyonu = sadece izlem değil, sağ hemikolektomi düşün.",
  "whyCorrect": "Patoloji raporunda çap ve mezoappendiks invazyonu ek lenfatik alan değerlendirmesini gerektiren risk profilini oluşturur.",
